class LibraryStore:
    def __init__(self, root, min_free_mb=400, max_file_mb=80, max_seconds=1800, quota_mb=0):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.min_free = int(min_free_mb) << 20
        self.max_file = int(max_file_mb) << 20
        self.max_seconds = max_seconds
        self.quota = int(quota_mb) << 20                    # 0 = 只受磁盘剩余空间限制(不设人为样本数量上限)
        self.lock = threading.RLock()
