MAGIC = b"VCENC1"


def _fernet(passphrase, salt):
    from cryptography.fernet import Fernet
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
    kdf = PBKDF2HMAC(algorithm=hashes.SHA256(), length=32, salt=salt, iterations=200_000)
    return Fernet(base64.urlsafe_b64encode(kdf.derive(passphrase.encode("utf-8"))))


def encrypt_bytes(data, passphrase):
    if not passphrase or len(passphrase) < 8:
        raise StoreError("加密口令至少 8 个字符")
    salt = os.urandom(16)
    return MAGIC + salt + _fernet(passphrase, salt).encrypt(data)


def decrypt_bytes(blob, passphrase):
    if not blob.startswith(MAGIC):
        raise StoreError("不是本系统的加密包")
    try:
        return _fernet(passphrase, blob[len(MAGIC):len(MAGIC) + 16]).decrypt(blob[len(MAGIC) + 16:])
    except Exception as e:  # noqa: BLE001
        raise StoreError("口令不正确或加密包已损坏") from e


