        if not self.store.idx.get("active") or self.store.idx["active"] not in self.store.idx["order"]:
            self.store.idx["active"] = idx.get("active") if idx.get("active") in self.store.idx["order"] else (self.store.idx["order"][0] if self.store.idx["order"] else None)
