    # ───────── 保存 / 导出 ─────────
    def checkpoint(self):
        """刷新清单(哈希)并记录保存时间;在 Kaggle 上这仍然只是「当前会话」,Save Version 之后才成为输出"""
        man = self.store.build_manifest()
        self.state.update(last_saved=now_iso(), files=man["n"])
