_WARM = {"t": 0.0, "cookies": None}


async def _get(url, params=None, headers=None):
    """统一的 HTTP GET:共享连接池 + 每域名并发/间隔限制;把 httpx 异常归类成 SearchError(kind),不泄露内部堆栈;429/503 的 Retry-After 会被解析并带出。"""
