VISUAL_PIXEL_DELTA = int(os.environ.get("VC_VERIFY_PIXEL_DELTA", "28"))          # 单个像素灰度差 > 它 才算「变了」(吸收 JPEG 噪声)
VISUAL_RATIO = float(os.environ.get("VC_VERIFY_VISUAL_RATIO", "0.0004"))         # 变化像素占比 ≥ 它 → 视觉变化。
# 提示词默认 1.5%@32×32(≈15 个像素格)。实测一个 16px 复选框在 32×32 缩略图里只占 0.3 格,根本检测不到,所以改成 1/4 尺度灰度 + 0.04%(≈ 一个小按钮);可用环境变量调回。
NET_WINDOW_S = float(os.environ.get("VC_VERIFY_NET_WINDOW", "1.5"))

SIG_JS = """() => { const d = document, b = d.body, de = d.documentElement; if (!b) return {ok:false};
  if (!window.__vcDocToken) window.__vcDocToken = Math.random().toString(36).slice(2);
  const main = d.querySelector('main,[role=main]') || b; const t = (main.innerText || '').slice(0, 4000);
  let h = 5381; for (let i = 0; i < t.length; i++) h = ((h << 5) + h + t.charCodeAt(i)) | 0;
  const a = d.activeElement; const ad = a ? (a.tagName.toLowerCase() + (a.id ? '#' + a.id : '') + (a.name ? '[' + a.name + ']' : '')) : '';
  return {ok:true, token: window.__vcDocToken, n: d.getElementsByTagName('*').length, tl: (b.innerText || '').length, th: h, active: ad,
          modal: d.querySelectorAll('dialog[open],[aria-modal=true]').length, sx: Math.round(window.scrollX), sy: Math.round(window.scrollY), rs: d.readyState, url: location.href,
          cls: (de.className || '').toString().slice(0, 120) + '|' + (b.className || '').toString().slice(0, 120)}; }"""
MO_ON_JS = """() => { try { if (window.__vcMO) window.__vcMO.disconnect(); window.__vcMOn = {c:0, a:0, d:0};
  window.__vcMO = new MutationObserver(ms => { for (const m of ms) { if (m.type === 'childList') window.__vcMOn.c += m.addedNodes.length + m.removedNodes.length; else if (m.type === 'attributes') window.__vcMOn.a++; else window.__vcMOn.d++; } });
  window.__vcMO.observe(document.documentElement, {subtree:true, childList:true, attributes:true, characterData:true}); return true; } catch (e) { return false; } }"""
MO_OFF_JS = """() => { try { const n = window.__vcMOn || {c:0,a:0,d:0}; if (window.__vcMO) { window.__vcMO.takeRecords(); window.__vcMO.disconnect(); } window.__vcMO = null; return n; } catch (e) { return {c:0,a:0,d:0}; } }"""
PROBE_JS = """([x, y]) => { const el = document.elementFromPoint(x, y); if (!el) return {tag:'', blank:true};
  const t = el.tagName.toLowerCase(); const dis = !!(el.disabled || (el.closest && el.closest('[disabled],[aria-disabled=true]')));
  const pw = !!document.querySelector('input[type=password]'); return {tag:t, blank:(t === 'html' || t === 'body'), disabled:dis, pw:pw, rs:document.readyState}; }"""


def frame_diff_ratio(a, b, delta=None):
    """两张 JPEG 的差异像素占比(1/4 尺度灰度)。需要 Pillow;没有 Pillow 返回 None(调用方如实标注「视觉层不可用」)。"""
    try:
        from PIL import Image, ImageChops
    except Exception:  # noqa: BLE001
        return None
    delta = VISUAL_PIXEL_DELTA if delta is None else delta
    try:
        def load(x):
            im = Image.open(io.BytesIO(x))
            im.draft("L", (max(1, im.width // 4), max(1, im.height // 4)))        # JPEG 解码时直接按 DCT 缩小,很快
            return im.convert("L")
        ia, ib = load(a), load(b)
        if ia.size != ib.size:
            ib = ib.resize(ia.size)
        diff = ImageChops.difference(ia, ib).point(lambda v: 255 if v > delta else 0)
        hist = diff.histogram()
        return hist[255] / float(ia.width * ia.height)
    except Exception:  # noqa: BLE001
        return None


def classify_nochange(probe, *, loading=False, blocked=False, covered=False, needs_login=False):
    """无变化时的原因分类(纯函数,可单测)。"""
    if blocked:
        return "blocked"
    if covered:
        return "covered"
    if probe and probe.get("disabled"):
        return "disabled"
    if loading:
        return "loading"
    if needs_login:
        return "needs_login"
    if probe and probe.get("blank"):
        return "blank_area"
    return "unknown"


REASON_ZH = {"blank_area": "点到了页面空白处(真实浏览器里这里本来就不会变化)", "covered": "目标被别的元素遮住了", "disabled": "该控件是禁用状态", "loading": "页面还在加载,稍后再看",
             "blocked": "请求被网络护栏/安全策略拦截", "needs_login": "可能需要先登录", "popup_blocked": "弹出窗口被拦截(标签页数已达上限)", "unknown": "没有检测到变化,原因不明(可能只是纯后台逻辑)"}
KIND_ZH = {"navigation": "页面跳转", "spa_route": "单页路由切换", "dom": "页面内容变化", "visual": "画面变化", "focus": "焦点变化", "scroll": "滚动", "dialog": "弹出对话框",
           "popup": "新标签页", "download": "开始下载", "network": "发起了网络请求"}
ACTIONS_NOCHANGE = ["retry", "move", "takeover", "remember"]        # 继续 / 换位置重试 / 人工接管 / 记住「此类控件不需变化」(前端按钮)


class Verifier:
    """会话级验证器。sess = BSession(需要 .page / .blocked / .v12 计数器)。"""

    def __init__(self, sess):
        self.s = sess

    async def _sig(self):
        try:
            r = await self.s.page.evaluate(SIG_JS)
            return r if isinstance(r, dict) and r.get("ok") else {}
        except Exception:  # noqa: BLE001
            return {}

    async def before(self, x=None, y=None, observe=True):
        s, v = self.s, self.s.v12
        pg = s.page
        ctx = {"t0": time.time(), "x": x, "y": y, "url": pg.url if pg else "", "sig": await self._sig(), "pages": len(s.pages), "blocked": s.blocked,
               "events": dict(v.counters), "frame": v.latest_frame_bytes(), "mo": False}
        if observe and pg is not None:
            try:
                ctx["mo"] = bool(await pg.evaluate(MO_ON_JS))
            except Exception:  # noqa: BLE001
                pass
        return ctx

    async def after(self, ctx, settle=True, target_covered=False):
        s, v = self.s, self.s.v12
        pg = s.page
        if settle:
            await s._settle()
        await v.frames_quiet()
        await asyncio.sleep(0)
        sig = await self._sig()
        mo = {"c": 0, "a": 0, "d": 0}
        if ctx.get("mo") and pg is not None:
            try:
                mo = await pg.evaluate(MO_OFF_JS)
            except Exception:  # noqa: BLE001
                pass
        kinds, ev0, ev = [], ctx["events"], v.counters
        old = ctx.get("sig") or {}
        if len(s.pages) > ctx["pages"] or ev["popup"] > ev0["popup"]:
            kinds.append("popup")
        if ev["dialog"] > ev0["dialog"]:
            kinds.append("dialog")
        if ev["download"] > ev0["download"]:
            kinds.append("download")
