        st.mark_candidate(lid, c2["candidate_id"], loaded=True, trial_synth=True)
        (md2 / "model.safetensors").write_bytes(b"tampered")
        raises(lambda: st.promote(lid, c2["candidate_id"]), libs.StoreError, "哈希")                     # 产物被改动 → 拒绝
        (md2 / "model.safetensors").write_bytes(b"weights-v2")
