def _chromium_ok():
    ok, why = ba.BrowserManager.available()
    if not ok:
        return False, why
    try:
        async def t():
            m = ba.BrowserManager()
            b = await m.browser()
            await m.shutdown()
            return True
        asyncio.run(t())
        return True, ""
    except Exception as e:  # noqa: BLE001
        return False, str(e)[:120]


def _with_fixture(fn):
    s1 = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Fixture)
    s2 = http.server.ThreadingHTTPServer(("127.0.0.1", 0), OtherSrv)
    for s in (s1, s2):
        threading.Thread(target=s.serve_forever, daemon=True).start()
    Fixture.other_port = s2.server_address[1]
    Fixture.hits.update(send=0, delete=0, secret=0)
    base = "http://127.0.0.1:%d" % s1.server_address[1]
    os.environ["VC_BROWSER_TEST_ALLOW"] = "127.0.0.1:%d" % s1.server_address[1]
    try:
        asyncio.run(fn(base))
    finally:
        os.environ.pop("VC_BROWSER_TEST_ALLOW", None)
        s1.shutdown()
        s2.shutdown()


async def _run(sess, actions, title="t", until=("done", "error", "cancelled", "paused", "waiting_confirm", "waiting_human"), timeout=40):
    sess.start(ba.validate_actions(actions), title)
    t0 = time.time()
    await asyncio.sleep(0.2)
    while time.time() - t0 < timeout:
        if sess.status in until and sess.status != "running":
            return sess.status
        await asyncio.sleep(0.15)
    return "timeout"


def test_browser_real_chromium_visible_actions_and_safety():
    ok, why = _chromium_ok()
    if not ok:
        SKIPPED.append("浏览器测试:未验证(%s)" % why)
        print("    ⚠ 跳过(未验证):%s" % why)
        return

    async def scenario(base):
        mgr = ba.BrowserManager()
        sess = mgr.get("sidA")
        sub = sess.subscribe()
        try:
            # 1) 打开 + 画面流:真实截图 JPEG
            assert await _run(sess, [{"action": "goto", "url": base + "/"}]) == "done"
            for _ in range(40):
                if sub.frame:
                    break
                await asyncio.sleep(0.15)
            assert sub.frame and sub.frame[:2] == b"\xff\xd8", "必须是真实的 JPEG 截图"
            # 2) 点击:鼠标指示坐标 = 元素真实中心;并核对页面变化
            sub.q.clear()
            assert await _run(sess, [{"action": "click", "by": "text", "value": "点我"}]) == "done"
            bb = await sess.page.locator("#b").bounding_box()
            cur = [e for e in sub.q if e.get("type") == "cursor" and e.get("kind") == "click"]
            assert cur and abs(cur[-1]["x"] - (bb["x"] + bb["width"] / 2)) <= 1 and abs(cur[-1]["y"] - (bb["y"] + bb["height"] / 2)) <= 1, (cur, bb)
            assert await sess.page.title() == "clicked"
            assert any(e["kind"] == "verify" for e in sess.log)
            # 3) 输入:真的输入到网页里,typing 事件逐步增长,输入后核对
            sub.q.clear()
            assert await _run(sess, [{"action": "type", "text": "你好abc", "into": {"by": "label", "value": "名字"}}]) == "done"
            assert await sess.page.input_value("#n") == "你好abc"
            tev = [e["text"] for e in sub.q if e.get("type") == "typing"]
            assert tev and tev[-1] == "你好abc" and len(set(tev)) > 1
            # 4) 滚动 / 返回 / 前进 / 刷新 / 读取
            assert await _run(sess, [{"action": "goto", "url": base + "/long"}, {"action": "scroll", "direction": "down", "amount": 800}]) == "done"
            assert await sess.page.evaluate("window.scrollY") > 300
            assert await _run(sess, [{"action": "back"}, {"action": "forward"}, {"action": "reload"}, {"action": "read"}]) == "done"
            assert sess.observation["untrusted"] and "第 1 段" in sess.observation["text"]
            # 5) 搜索(可见):用本地假搜索引擎走完整的“打开→点搜索框→真实键入→回车→解析”
            ba.ENGINES["fake"] = {"name": "fake", "home": base + "/searchhome", "box": 'input[name="q"]', "js": ba.DDG_JS, "page": lambda q, p: base + "/search?" + urllib.parse.urlencode({"q": q, "p": p}), "recency": {}, "rec_param": None}
            sub.q.clear()
            assert await _run(sess, [{"action": "search", "query": "量子 计算", "engine": "fake"}]) == "done"
            assert len(sess.last_results) == 3 and sess.last_results[0]["domain"] == "127.0.0.1" and sess.last_results[0]["fetched_at"].endswith("Z") and "量子 计算" in sess.last_results[0]["title"]
            assert [e["text"] for e in sub.q if e.get("type") == "typing"][-1] == "量子 计算"
            assert await _run(sess, [{"action": "open_result", "n": 2}]) == "done" and sess.page.url.endswith("/doc2")
            assert await _run(sess, [{"action": "search_more"}]) == "done" and sess.search_page == 1
            # 6) 危险操作:发送表单 → 先确认;拒绝则不提交;同意才提交
            assert await _run(sess, [{"action": "goto", "url": base + "/form"}, {"action": "click", "by": "text", "value": "Send message"}]) == "waiting_confirm"
            assert Fixture.hits["send"] == 0, "确认前不得提交"
            pend = sess.pending
            assert pend and "127.0.0.1" in pend["site"] and "提交表单" in pend["consequence"]
            sess.answer_confirm(pend["id"], False)
            for _ in range(40):
                if sess.status == "error":
                    break
                await asyncio.sleep(0.1)
            assert sess.status == "error" and Fixture.hits["send"] == 0
            assert await _run(sess, [{"action": "goto", "url": base + "/form"}, {"action": "click", "by": "text", "value": "Send message"}]) == "waiting_confirm"
            sess.answer_confirm(sess.pending["id"], True)
            for _ in range(60):
                if sess.status == "done":
                    break
                await asyncio.sleep(0.15)
            assert sess.status == "done" and Fixture.hits["send"] == 1
            # 7) 密码字段:拒绝自动输入
            assert await _run(sess, [{"action": "goto", "url": base + "/login"}, {"action": "type", "text": "hunter2", "into": {"by": "label", "value": "密码"}}]) == "error"
            assert "拒绝" in sess.msg and "hunter2" not in json.dumps(list(sess.log), ensure_ascii=False)
            # 8) 提示词注入页:读取页面只产生"不可信数据",不会点击 Delete / 执行任何东西
            assert await _run(sess, [{"action": "goto", "url": base + "/inject"}, {"action": "read"}]) == "done"
            assert "IGNORE ALL PREVIOUS" in sess.observation["text"] and sess.observation["untrusted"] and Fixture.hits["delete"] == 0
            # 9) 验证码页 → 暂停交给用户,不绕过
            assert await _run(sess, [{"action": "goto", "url": base + "/captcha"}]) == "waiting_human"
            sess.cancel()
            await asyncio.sleep(0.3)
            # 10) 安全边界:file: / 内网 / 元数据 / 重定向到未放行端口 全部被拒绝
            for bad in ("file:///etc/passwd", "http://169.254.169.254/latest/meta-data/", "javascript:alert(1)", "http://localhost:1/", "http://%s/" % ("127.0.0.1:%d" % Fixture.other_port)):
                st = await _run(sess, [{"action": "goto", "url": bad}])
                assert st == "error" and "拒绝" in sess.msg or "阻止" in sess.msg, (bad, st, sess.msg)
            assert await _run(sess, [{"action": "goto", "url": base + "/redir"}]) == "error"
            assert Fixture.hits["secret"] == 0, "重定向到未放行地址必须被拦截,服务端不得收到请求"
            assert sess.blocked >= 1
            # 11) 暂停 / 继续 / 取消
            sess.start(ba.validate_actions([{"action": "wait", "seconds": 3}, {"action": "wait", "seconds": 3}, {"action": "snapshot"}]), "slow")
            await asyncio.sleep(0.8)
            sess.pause()
            assert sess.status == "paused"
            n = sess.steps_done
            await asyncio.sleep(3.5)
            assert sess.steps_done <= n + 1 and sess.status == "paused"
            sess.resume()
            await asyncio.sleep(0.5)
            assert sess.status in ("running", "done")
            sess.cancel()
            await asyncio.sleep(0.5)
            assert sess.status == "cancelled"
            # 12) 人工接管:点击与输入(输入内容不记录)
            await _run(sess, [{"action": "goto", "url": base + "/"}])
            await sess.human({"kind": "click", "x": 5, "y": 5})
            await sess.page.locator("#n").click()
            await sess.human({"kind": "type", "text": "秘密口令123"})
            assert await sess.page.input_value("#n") == "秘密口令123"
            assert "秘密口令123" not in json.dumps(list(sess.log), ensure_ascii=False) and any(e["kind"] == "user" for e in sess.log)
            # 13) 步数上限 / 队列上限
            raises(lambda: ba.validate_actions([{"action": "snapshot"}] * (ba.MAX_STEPS + 1)), ValueError, "上限")
        finally:
            sess.unsubscribe(sub)
            await mgr.shutdown()

    _with_fixture(scenario)


def test_browser_session_isolation_and_cleanup():
    ok, why = _chromium_ok()
    if not ok:
        SKIPPED.append("浏览器隔离测试:未验证(%s)" % why)
        return

    async def scenario(base):
        mgr = ba.BrowserManager()
        a, b = mgr.get("A"), mgr.get("B")
        try:
            assert await _run(a, [{"action": "goto", "url": base + "/cookie/set"}, {"action": "goto", "url": base + "/cookie/get"}]) == "done"
            assert "sessionA" in await a.page.inner_text("#c")
            assert await _run(b, [{"action": "goto", "url": base + "/cookie/get"}]) == "done"
            assert "sessionA" not in await b.page.inner_text("#c"), "不同会话不得共用 Cookie"
            for i in range(ba.MAX_SESSIONS - 2):
                mgr.get("X%d" % i)
            raises(lambda: mgr.get("overflow"), ba.ActionError, "上限")
            await mgr.close_session("A")                                                       # 关闭 = 登录状态清除
            a2 = mgr.get("A")
            assert await _run(a2, [{"action": "goto", "url": base + "/cookie/get"}]) == "done"
            assert "sessionA" not in await a2.page.inner_text("#c")
        finally:
            await mgr.shutdown()
    _with_fixture(scenario)


