# ═════════════════════ 免 Key 搜索 ═════════════════════
BING_HTML = """<html><body><div id="b_content"><ol id="b_results">
<li class="b_algo"><h2><a href="https://example.org/a">示例 <strong>结果</strong> A</a></h2><div class="b_caption"><p class="b_lineclamp2">这是 A 的摘要 &amp; 说明</p></div></li>
<li class="b_algo"><h2><a href="https://www.bing.com/ck/a?!&&p=x&u=a1aHR0cHM6Ly9leGFtcGxlLmNvbS9i&ntb=1">示例结果 B</a></h2><div class="b_caption"><p>B 的摘要</p></div></li>
<li class="b_algo"><h2><a href="http://127.0.0.1/evil">内网链接必须被丢弃</a></h2><p>x</p></li>
</ol></div></body></html>"""
DDG_HTML = """<html><body><div class="results"><div class="result results_links"><h2 class="result__title"><a class="result__a" href="//duckduckgo.com/l/?uddg=https%3A%2F%2Fexample.net%2Fz&amp;rut=1">DDG 结果 Z</a></h2>
<a class="result__snippet" href="x">Z 的摘要</a></div></div></body></html>"""
WIKI_JSON = json.dumps({"query": {"search": [{"title": "测试条目", "snippet": "片段 <span>高亮</span>"}]}})


class FakeSite(http.server.BaseHTTPRequestHandler):
    modes = {"bing": "ok", "ddg": "ok", "wiki": "ok"}
    hits = {"bing": 0, "ddg": 0, "wiki": 0}

    def log_message(self, *a):
        pass

    def do_GET(self):
        key = "bing" if self.path.startswith("/search") else "ddg" if self.path.startswith("/html") else "wiki"
        FakeSite.hits[key] += 1
        mode = FakeSite.modes[key]
        body, code, ct = b"", 200, "text/html; charset=utf-8"
        if mode == "ok":
            body = {"bing": BING_HTML, "ddg": DDG_HTML, "wiki": WIKI_JSON}[key].encode()
            ct = "application/json" if key == "wiki" else ct
        elif mode == "503":
            code, body = 503, b"<html>Service Unavailable</html>"
        elif mode == "429":
            code, body = 429, b"slow down"
        elif mode == "challenge":
            body = b"<html><body>Our systems have detected unusual traffic. captcha</body></html>"
        elif mode == "empty":
            body = "<html><body><div id='b_content'><ol id='b_results'><li class=\"b_no\">没有找到与 x 相关的结果</li></ol></div></body></html>".encode()
        elif mode == "changed":
            body = b"<html><body><div id='b_results'><div class='new_layout'>x</div></div></body></html>"
        self.send_response(code)
        self.send_header("Content-Type", ct)
        self.end_headers()
        self.wfile.write(body)


def _fake_site():
    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), FakeSite)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    return srv, "http://127.0.0.1:%d" % srv.server_address[1]


def test_unit_search_parsers_real_format_and_filtering():
    import search_providers as sp
    raw = sp.parse_bing(BING_HTML)
    assert [r["title"] for r in raw][:2] == ["示例 结果 A", "示例结果 B"], raw
    assert raw[0]["snippet"] == "这是 A 的摘要 & 说明" and raw[1]["url"] == "https://example.com/b"           # Bing 跳转链接被解包
    res = sp._clean(raw, "http:bing", 0, 8)
    assert len(res) == 2 and all(r["url"].startswith("https://") and r["domain"] and r["provider"] == "http:bing" and r["fetched_at"] for r in res)   # 内网链接被丢弃
    d = sp.parse_ddg(DDG_HTML)
    assert d and d[0]["url"] == "https://example.net/z" and d[0]["snippet"] == "Z 的摘要", d


def test_unit_search_chain_fallback_errors_and_no_retry_policy():
    import search_providers as sp
    srv, base = _fake_site()
    old = dict(sp.BASES)
    sp.BASES.update(bing=base, duckduckgo=base, wikipedia=base)
    try:
        FakeSite.modes.update(bing="ok", ddg="ok", wiki="ok")
        res, pid, att = asyncio.run(_chain("测试", 8))
        assert pid == "http:bing+duckduckgo" and len(res) == 3 and att[0]["ok"] and att[1]["ok"]      # v8:Bing 只有 2 条(<8)→ 合并 DDG 的 1 条
        # Bing 持续 5xx:可重试 → 重试 1 次后失败 → 自动切到 DuckDuckGo;失败原因与实际 provider 都可见
        FakeSite.modes.update(bing="503")
        FakeSite.hits.update(bing=0, ddg=0, wiki=0)
        res, pid, att = asyncio.run(_chain("测试", 8))
        assert pid == "http:duckduckgo" and FakeSite.hits["bing"] == 2, FakeSite.hits
        assert att[0]["provider"] == "bing" and att[0]["kind"] == "server_error" and att[0]["tries"] == 2 and att[-1]["ok"]
        # 429 / 验证码页:不可重试(只请求 1 次),且不绕过
        for mode, kind in (("429", "rate_limited"), ("challenge", "challenge"), ("empty", "empty"), ("changed", "parse")):
            FakeSite.modes.update(bing=mode, ddg="ok")
            FakeSite.hits.update(bing=0)
            res, pid, att = asyncio.run(_chain("测试", 8))
            assert att[0]["kind"] == kind and FakeSite.hits["bing"] == 1 and pid == "http:duckduckgo", (mode, att[0], FakeSite.hits)
        # 全部失败 → SearchFailed,携带每次尝试;维基百科最后兜底
        FakeSite.modes.update(bing="503", ddg="challenge", wiki="ok")
        res, pid, att = asyncio.run(_chain("日期", 8))
        assert pid == "http:wikipedia" and res[0]["url"].endswith("/wiki/%E6%B5%8B%E8%AF%95%E6%9D%A1%E7%9B%AE") and res[0]["snippet"] == "片段 高亮"
        FakeSite.modes.update(wiki="503")
        try:
            asyncio.run(_chain("日期", 8))
            raise AssertionError("应当失败")
        except sp.SearchFailed as e:
            kinds = [a["kind"] for a in e.attempts]
            assert kinds[:2] == ["server_error", "challenge"] and "wikipedia" in e.attempts[-1]["provider"] and "遇到验证码" in str(e)
    finally:
        sp.BASES.update(old)
        srv.shutdown()


def test_unit_search_network_down_is_reported_as_network():
    import search_providers as sp
    import socket
    s = socket.socket()
    s.bind(("127.0.0.1", 0))
    port = s.getsockname()[1]
    s.close()                                                                  # 关闭的端口 = 断网的替身
    old = dict(sp.BASES)
    dead = "http://127.0.0.1:%d" % port
    sp.BASES.update(bing=dead, duckduckgo=dead, wikipedia=dead)
    try:
        try:
            asyncio.run(_chain("x", 8))
            raise AssertionError("应当失败")
        except sp.SearchFailed as e:
            assert all(a["kind"] == "network" for a in e.attempts) and len(e.attempts) == 3 and "网络不可用" in str(e)
    finally:
        sp.BASES.update(old)


