def test_interrupted_part_not_downloadable_and_restart_listing():
    tmp = tempfile.mkdtemp()
    try:
        st = mk(tmp)
        good = run_turn_sim(st, [(b"", [tone(1.0)])])
        d = Path(tmp) / "libA" / ("t_" + "ab" * 8)
        d.mkdir(parents=True)
        (d / "turn.wav.part").write_bytes(b"RIFF....")
        st2 = mk(tmp)                                           # 模拟进程重启
        rows = {r["artifact_id"]: r for r in st2.list("libA")}
        assert rows[good.aid]["downloadable"] and rows[good.aid]["status"] == "ready"
        bad = rows["t_" + "ab" * 8]
        assert bad["status"] == "failed" and not bad["downloadable"] and "中断" in bad["reason"]
        assert st2.resolve(good.aid, "libA", "turn")[1]["sha256"] == rows[good.aid]["sha256"]
        (Path(tmp) / "libA" / good.aid / "turn.wav").unlink()   # 文件被删 → expired
        st3 = mk(tmp)
        assert {r["artifact_id"]: r for r in st3.list("libA")}[good.aid]["status"] == "expired"
        try:
            st3.resolve(good.aid, "libA", "turn")
            raise AssertionError
        except art.ArtifactError as e:
            assert e.http == 410
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_security_isolation_traversal_corruption():
    tmp = tempfile.mkdtemp()
    try:
        st = mk(tmp)
        r = run_turn_sim(st, [(b"", [tone(1.0)])])
        for bad in ("../../etc/passwd", "t_zz", "", "t_" + "0" * 16 + "/../x"):
            try:
                st.manifest(bad, "libA")
                raise AssertionError(bad)
            except art.ArtifactError as e:
                assert e.http in (400, 404)
        try:
            st.resolve(r.aid, "libB", "turn")                     # 其他语音库:当作不存在
            raise AssertionError("语音库隔离失败")
        except art.ArtifactError as e:
            assert e.http == 404
        assert st.list("libB") == []
        try:
            st.resolve(r.aid, "libA", "segment", "../../x")
            raise AssertionError
        except art.ArtifactError as e:
            assert e.http == 400
        m = st.disk_manifests[r.aid]
        orig = m["turn_file"]["file"]
        m["turn_file"]["file"] = "../../../../etc/passwd"           # 清单被篡改:路径穿越必须被拒
        try:
            st.resolve(r.aid, "libA", "turn")
            raise AssertionError("路径穿越")
        except art.ArtifactError as e:
            assert e.http in (409, 410)
        m["turn_file"]["file"] = orig
        p = Path(tmp) / "libA" / r.aid / "turn.wav"
        data = bytearray(p.read_bytes())
        data[1000] ^= 0xFF                                         # 位翻转:大小不变,verify 必须发现
        p.write_bytes(bytes(data))
        assert st.verify(r.aid, "libA")["ok"] is False
        p.write_bytes(bytes(data[:-100]))                          # 截断:大小与清单不符 → 拒绝下载
        try:
            st.resolve(r.aid, "libA", "turn")
            raise AssertionError
        except art.ArtifactError as e:
            assert e.http == 409
        assert st.delete(r.aid, "libA") and not (Path(tmp) / "libA" / r.aid).exists()
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_zip_flac_and_purge_scope():
    tmp = tempfile.mkdtemp()
    try:
        st = mk(tmp)
        st.store_text = False
        a = run_turn_sim(st, [(b"", [tone(1.0, seed=1)]), (zeros(0.3), [tone(1.0, 300, seed=2)])], lib="libA", uid=1)
        b = run_turn_sim(st, [(b"", [tone(1.0, seed=3)])], lib="libB", uid=2)
        z = st.build_zip([a.aid], "libA")
        with zipfile.ZipFile(z) as zf:
            names = zf.namelist()
            assert any(n.endswith("turn_full.wav") for n in names) and sum("segments/" in n for n in names) == 2 and any(n.endswith("manifest.json") for n in names)
            man = json.loads(zf.read([n for n in names if n.endswith("manifest.json")][0]))
            blob = json.dumps(man, ensure_ascii=False)
            assert "text" not in man and "voice" not in blob.lower() and man["synthetic"] is True and man["turn_file"]["sha256"]
            assert zf.testzip() is None
        z.unlink()
        try:
            st.build_zip([b.aid], "libA")                          # 不能把别的语音库打进包
            raise AssertionError
        except art.ArtifactError as e:
            assert e.http == 404
        p, fe, _ = st.resolve(a.aid, "libA", "turn")
        f = st.to_flac(p, fe)
        import soundfile as sf
        d, sr = sf.read(str(f), dtype="int16")
        assert sr == SR and d.astype("<i2").tobytes() == wav_pcm(p)[3], "FLAC 必须与 WAV 逐样本相同"
        assert st.purge("libA") == 1 and st.list("libA") == [] and len(st.list("libB")) == 1, "清理范围必须只限指定语音库"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def test_range_parser():
    assert art.parse_range(None, 100) is None
    assert art.parse_range("bytes=0-9", 100) == (0, 9) and art.parse_range("bytes=90-", 100) == (90, 99) and art.parse_range("bytes=-10", 100) == (90, 99)
    assert art.parse_range("bytes=50-500", 100) == (50, 99) and art.parse_range("bytes=0-1,5-6", 100) is None
    for bad in ("bytes=100-", "bytes=9-3", "bytes=-0"):
        try:
            art.parse_range(bad, 100)
            raise AssertionError(bad)
        except art.ArtifactError as e:
            assert e.http == 416


# ───────────────────────── Mock 集成测试(真实 HTTP + WebSocket + 双 GPU worker) ─────────────────────────
def http(srv, path, method="GET", headers=None, opener=None):
    req = urllib.request.Request(srv.url(path), method=method, headers=headers or {})
    try:
        r = (opener or urllib.request.build_opener()).open(req, timeout=60)
        return r.status, dict((k.lower(), v) for k, v in r.headers.items()), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict((k.lower(), v) for k, v in e.headers.items()), e.read()


async def play_turn(port, text, sid="a1"):
    import websockets
    ws = await websockets.connect("ws://127.0.0.1:%d/ws" % port, max_size=None)
    await ws.send(json.dumps({"type": "hello", "sid": sid}))
    await ws.send(json.dumps({"type": "say", "text": text, "opts": {"tts": True}}))
    uid, got, done, msgs, played, t0 = None, [], None, [], 0, None
    last_ack = time.time()
    while True:
        m = await asyncio.wait_for(ws.recv(), 30)
        if isinstance(m, (bytes, bytearray)):
            u = pr.unpack_frame(bytes(m))
            got.append(u["pcm"])
            if t0 is None:
                t0 = time.time()
        else:
            j = json.loads(m)
            msgs.append(j)
            if j["type"] == "turn_start":
                uid = j["turn"]
            if j["type"] == "turn_done":
                done = j
        if uid is not None and time.time() - last_ack > 0.25:
            n = sum(len(x) for x in got) // 2
            await ws.send(json.dumps({"type": "ack", "turn": uid, "next_seq": len(got), "played": min(n, int((time.time() - (t0 or time.time())) * SR)), "level_ms": 0}))
            last_ack = time.time()
        if done is not None and any(len(x) == 0 for x in got[-1:]):
            break
    await ws.close()
    return {"uid": uid, "pcm": b"".join(got), "done": done, "msgs": msgs}


TEXT = "今天天气真好，我们一起出去走走吧。路上可以看看花，也可以拍几张照片。回来的时候，顺便买一点水果，晚上一起吃。你觉得这样安排怎么样？我觉得挺好的。"


def wait_ready(srv, n, opener=None, timeout=30):
    t0 = time.time()
    while time.time() - t0 < timeout:
        s, _, b = http(srv, "/api/artifacts", opener=opener)
        j = json.loads(b)
        rows = j.get("turns", [])
        if len(rows) >= n and all(r["status"] not in ("generating", "finalizing") for r in rows):
            return j
        time.sleep(0.3)
    raise AssertionError("产物没有在时限内完成: %s" % [r["status"] for r in rows])


def _is_pause(b):
    """停顿 = 数字零(v14 / V15 关闭)或 v15 舒适噪声(峰值 ≤ 300、RMS ≤ 60,约 -57dBFS 以下)。"""
    if not any(b):
        return True
    import numpy as _np
    x = _np.frombuffer(b[: len(b) // 2 * 2], dtype="<i2").astype(_np.float64)
    return bool(len(x)) and float(_np.abs(x).max()) <= 300 and float(_np.sqrt((x ** 2).mean())) <= 60


def test_integration_mock_downloads():
    from test_gateway import Server
    srv = Server(VC_MOCK_FAIL="")
    try:
        srv.clone()
        results = [asyncio.run(play_turn(srv.port, TEXT, sid="s%d" % i)) for i in range(5)]       # 5 轮 > 旧版 3 轮上限
        j = wait_ready(srv, 5)
        assert len(j["turns"]) == 5 and all(t["downloadable"] for t in j["turns"]), [t["status"] + ":" + t["reason"] for t in j["turns"]]
        by_uid = {t["turn_uid"]: t for t in j["turns"]}
        multi_gpu = False
        for r in results:
            t = by_uid[r["uid"]]
            assert r["done"]["artifact_id"] == t["artifact_id"] and r["done"]["synthetic"] is True
            aid = t["artifact_id"]
            s, h, body = http(srv, "/api/artifacts/%s/turn.wav" % aid)
            assert s == 200 and h["content-type"] == "audio/wav" and "attachment" in h["content-disposition"] and int(h["content-length"]) == len(body)
            assert h["etag"].strip('"') == hashlib.sha256(body).hexdigest() == t["sha256"] and "private" in h["cache-control"]
            with wave.open(io.BytesIO(body)) as w:
                assert (w.getframerate(), w.getnchannels(), w.getsampwidth()) == (SR, 1, 2)
                pcm = w.readframes(w.getnframes())
            assert pcm == r["pcm"], "下载的整轮文件必须与浏览器实际收到的 PCM 逐字节一致(含句间停顿)"
            man = json.loads(http(srv, "/api/artifacts/" + aid)[2])["manifest"]
            assert man["turn_file"]["matches_emitted_frames"] is True and len(man["segments"]) >= 3
            cur = 0
            for sg in man["segments"]:                        # 每段单独文件:按顺序出现在整轮里,段间只有零(停顿)
                s2, _, sb = http(srv, "/api/artifacts/%s/segments/%s.wav" % (aid, sg["id"]))
                assert s2 == 200
                with wave.open(io.BytesIO(sb)) as w:
                    sp = w.readframes(w.getnframes())
                at = pcm.find(sp, cur)
                assert at >= cur, "单段内容不在整轮里/顺序错误"
                assert _is_pause(pcm[cur:at]), "段间只能是静音停顿(v14=数字零;v15=低电平舒适噪声)"
                cur = at + len(sp)
            assert _is_pause(pcm[cur:])
            multi_gpu = multi_gpu or len(r["done"]["gpu_segs"]) > 1
            assert http(srv, "/api/artifacts/%s/verify" % aid)[2] and json.loads(http(srv, "/api/artifacts/%s/verify" % aid)[2])["ok"]
        assert multi_gpu, "Mock 双 GPU 并行应使至少一轮跨两张卡(乱序到达路径被覆盖)"
        aid = j["turns"][0]["artifact_id"]
        s, h, full = http(srv, "/api/artifacts/%s/turn.wav" % aid)
        s, h, part = http(srv, "/api/artifacts/%s/turn.wav" % aid, headers={"Range": "bytes=100-1099"})
        assert s == 206 and part == full[100:1100] and h["content-range"] == "bytes 100-1099/%d" % len(full)
        s, h, tail = http(srv, "/api/artifacts/%s/turn.wav" % aid, headers={"Range": "bytes=-500"})
        assert s == 206 and tail == full[-500:]
        assert http(srv, "/api/artifacts/%s/turn.wav" % aid, headers={"Range": "bytes=%d-" % (len(full) + 5)})[0] == 416
        s, h, _ = http(srv, "/api/artifacts/%s/turn.wav" % aid, method="HEAD")
        assert s == 200 and int(h["content-length"]) == len(full)
        assert http(srv, "/api/artifacts/%s/turn.wav" % aid, headers={"If-None-Match": h["etag"]})[0] == 304
        s, h, fl = http(srv, "/api/artifacts/%s/turn.wav?format=flac" % aid)
        assert s == 200 and h["content-type"] == "audio/flac"
        import soundfile as sf
        d, sr = sf.read(io.BytesIO(fl), dtype="int16")
        assert d.astype("<i2").tobytes() == full[44:]
        # 错误请求
        assert http(srv, "/api/artifacts/t_0000000000000000/turn.wav")[0] == 404
        assert http(srv, "/api/artifacts/..%2f..%2fetc%2fpasswd/turn.wav")[0] in (400, 404)
        assert http(srv, "/api/artifacts/%s/segments/s_0000000000.wav" % aid)[0] == 404
        # ZIP
        s, h, zb = http(srv, "/api/artifacts/zip")
        assert s == 200 and h["content-type"] == "application/zip" and int(h["content-length"]) == len(zb)
        with zipfile.ZipFile(io.BytesIO(zb)) as zf:
            assert zf.testzip() is None and sum(n.endswith("turn_full.wav") for n in zf.namelist()) == 5
        # 并行下载
        import concurrent.futures as cf
        with cf.ThreadPoolExecutor(6) as ex:
            outs = list(ex.map(lambda _: http(srv, "/api/artifacts/%s/turn.wav" % aid)[2], range(8)))
        assert all(o == full for o in outs)
        # 旧接口兼容
        s, h, old = http(srv, "/api/gen/%d.wav" % results[0]["uid"])
        assert s == 200 and old[:4] == b"RIFF" and len(old) > 1000
        # 清理范围需要明确确认
        assert http(srv, "/api/artifacts", method="DELETE")[0] == 400
        assert http(srv, "/api/artifacts/%s" % aid, method="DELETE")[0] == 200 and http(srv, "/api/artifacts/%s/turn.wav" % aid)[0] == 404
        # 进程重启后仍可列出并下载(同一 VC_WORK)
        tmpdir = srv.tmp
        keep = j["turns"][1]
        keep_sha = keep["sha256"]
    finally:
        srv.stop()
    srv2 = None
    try:
        from test_gateway import Server as S2
        srv2 = S2.__new__(S2)
        # 复用工作目录启动新进程
        import socket
        import subprocess
        srv2.port = (lambda s: (s.bind(("127.0.0.1", 0)), s.getsockname()[1], s.close())[1])(socket.socket())
        srv2.tmp = tmpdir
        e = dict(os.environ, VC_MOCK="1", VC_MOCK_LLM="1", VC_PORT=str(srv2.port), VC_WORK=tmpdir, PYTHONPATH=str(HERE), PYTHONUNBUFFERED="1", VC_EVAL_LOG=tmpdir + "/e.jsonl",
                 VC_TRAIN_STATE=tmpdir + "/t.json", VC_REPORT_DIR=tmpdir + "/rep", VC_DIAG_DIR=tmpdir + "/diag", VC_REF_FORCE="0")
        srv2.p = subprocess.Popen([sys.executable, str(HERE / "app.py")], env=e, cwd=str(HERE), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        t0 = time.time()
        while time.time() - t0 < 40:
            try:
                urllib.request.urlopen(srv2.url("/health"), timeout=2)
                break
            except Exception:
                time.sleep(0.3)
        rows = json.loads(http(srv2, "/api/artifacts")[2])["turns"]
        # 重启后语音库为空(未选库)→ 库隔离:库 None 下的产物才可见。mock 克隆无语音库 → library_id None,所以应可见
        got = {r["artifact_id"]: r for r in rows}
        assert keep["artifact_id"] in got and got[keep["artifact_id"]]["status"] == "ready", (list(got), keep)
        s, h, b = http(srv2, "/api/artifacts/%s/turn.wav" % keep["artifact_id"])
        assert s == 200 and hashlib.sha256(b).hexdigest() == keep_sha
    finally:
        if srv2 is not None:
            srv2.stop()


