def test_server_http_profile_vision_endpoints_without_consent():
    import test_gateway as tg
    import test_portal as tp
    srv, tg_ = tp._server()
    try:
        H = lambda m, p, b=None: tp._http(srv, m, p, b, headers={"Origin": "http://127.0.0.1:%d" % srv.port})
        c, j, _ = H("GET", "/api/agent/profiles")
        assert c == 200 and set(j["profiles"]) == {"compat", "hd", "uhd"} and j["profiles"]["uhd"]["w"] == 1920, j
        c, j, _ = H("POST", "/api/agent/profile", {"profile": "nope"})
        assert c == 409 and not j["ok"], (c, j)
        c, j, _ = H("POST", "/api/agent/profile", {"profile": "compat"})                          # 没有上下文:直接生效
        assert c == 200 and j["profile"] == "compat" and j["view"] == {"w": 1280, "h": 800}, (c, j)
        c, j, _ = H("POST", "/api/agent/vision_locate", {"goal": "登录按钮"})                      # 没有页面
        assert c == 409, (c, j)
        c, j, _ = H("GET", "/api/portal/status")
        assert j["llm"]["vision"] == "unconfigured" and "规则" in j["llm"]["vision_zh"], j["llm"]
        # click_at 经 /api/agent/run 也要过服务端校验:缺字段 → 400
        c, j, _ = H("POST", "/api/agent/run", {"actions": [{"action": "click_at", "nx": 0.5}], "title": "x"})
        assert c == 400, (c, j)
    finally:
        srv.stop()


