            pg.wait_for_function("(() => { const f = WBSTATE.frame; return f && f.vw === 1920 && document.getElementById('bstat').textContent.includes(f.pw + '×' + f.ph); })()", timeout=15000)
            st = pg.inner_text("#bstat")
