BAD5 = "第一句很正常。第二句也很正常。第三句依旧正常。第四句还是正常的。第五句 RUNAWAYLATE 收尾说得长一点好吗。"


def v14state(srv):
    return json.load(urllib.request.urlopen(srv.url("/api/v14/state"), timeout=5))


def wav16(x):
    b = io.BytesIO()
    with wave.open(b, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(16000)
        w.writeframes((np.clip(x, -1, 1) * 32767).astype("<i2").tobytes())
    return b.getvalue()


def http(srv, method, path, data=None, ctype="application/octet-stream"):
    req = urllib.request.Request(srv.url(path), data=data, method=method, headers={"Content-Type": ctype})
    try:
        return json.load(urllib.request.urlopen(req, timeout=60))
    except urllib.error.HTTPError as e:
        return dict(json.loads(e.read().decode() or "{}"), _status=e.code)


