    """GPU0 对该句必定失控(抢救关闭)→ 另一张卡换种子/降温重试 → 成功;dropped=0。"""
    text = "第一句很正常。" + "".join("第%d句 RUNAWAYLATE 这一句要说得稍微长一点点。" % i for i in range(2, 8))
