        assert r["done"] and r["pcm"].size > 0 and not r["done"]["errors"]
        st = v14state(srv)
        assert st["dialog"]["counts"]["ignored_other"] >= 3 and st["dialog"]["counts"]["accepted"] >= 2 and st["lock"]["samples"]["owner"] >= 1
        # 模式切换 / 关闭后放行 / 真删除
        assert http(srv, "POST", "/api/v14/lock/mode?mode=off")["mode"] == "off"
        assert utt(u14.voice(*u14.OTHER1, 3.0, 47))["ok"]
        assert http(srv, "POST", "/api/v14/lock/mode?mode=strict")["mode"] == "strict"
        assert http(srv, "POST", "/api/v14/lock/mode?mode=bogus")["_status"] == 400
        d = http(srv, "DELETE", "/api/v14/lock")
