    """像浏览器一样收一整轮:返回 PCM(int16)、JSON 消息、turn_done。"""
    import websockets
    ws = await websockets.connect("ws://127.0.0.1:%d/ws" % port, max_size=None)
    await ws.send(json.dumps({"type": "hello", "sid": sid}))
    await ws.send(json.dumps({"type": kind, "text": text, "opts": {"tts": True}}))
    chk, msgs, pcm, uid, done = None, [], [], None, None
    t_start, got, t_ack, t_begin = None, 0, 0.0, time.time()
