# ───────── M2 闸门 + 谱系 ─────────
def _base(n=24):
    rng = np.random.default_rng(0)
    return {"sim": 0.80 + rng.normal(0, 0.01, n), "cer": 0.05 + rng.normal(0, 0.005, n), "defect_rate": np.zeros(n), "utmos": 3.5 + rng.normal(0, 0.05, n), "hf_floor_db": -70 + rng.normal(0, .3, n)}


def _chal(base, **fx):
    c = {k: np.array(v) for k, v in base.items()}
    c["red_defects"] = np.zeros(len(c["sim"]))
    for k, f in fx.items():
        c[k] = f(c[k])
    return c


def test_gate_rejects_worse_and_accepts_better():
    b = _base()
    assert v17.gate_decide(b, _chal(b, sim=lambda a: a + 0.03))["promote"]
    assert not v17.gate_decide(b, _chal(b, sim=lambda a: a - 0.03))["promote"], "更差候选必须被拒"
    assert not v17.gate_decide(b, _chal(b))["promote"], "无显著提升保持冠军"
    assert not v17.gate_decide(b, _chal(b, sim=lambda a: a + 0.03, cer=lambda a: a + 0.05))["promote"]
    assert not v17.gate_decide(b, _chal(b, sim=lambda a: a + 0.03, hf_floor_db=lambda a: a + 5))["promote"], "沙沙声变大必须被拒"
    c = _chal(b, sim=lambda a: a + 0.03); c["red_defects"] = np.r_[np.ones(2), np.zeros(len(c["sim"]) - 2)]
    assert not v17.gate_decide(b, c)["promote"], "出现红色缺陷必须被拒"
    nb = {k: v for k, v in b.items() if k != "cer"}
    assert not v17.gate_decide(nb, _chal(b, sim=lambda a: a + 0.03))["promote"], "必需指标缺失=未验证=不晋升"


def test_lineage_promote_rollback_canary_and_persistence():
    d = tempfile.mkdtemp(); p = os.path.join(d, "l.json")
    L = v17.Lineage(p); L.ensure_v0(snapshot="a")
