# ───────── 提示词搜索 / 体检 / Studio / 路由 ─────────
def test_prompt_search_is_reproducible_and_respects_flags():
    rng = np.random.default_rng(0)
    segs = [{"id": "s%02d" % i, "seconds": float(rng.uniform(3, 9)), "quality": float(rng.uniform(55, 95)), "emb": rng.normal(size=16), "cond": "A" if i < 8 else "B", "enabled": True, "verified": True} for i in range(12)]
    segs[3]["enabled"] = False; segs[5]["verified"] = False
    a, b = v17.mmr_select(segs, seed=7), v17.mmr_select(segs, seed=7)
    assert a == b and "s03" not in a and "s05" not in a
    assert sum(s["seconds"] for s in segs if s["id"] in a) <= 20.0 + 1e-6
    assert len({s["cond"] for s in segs if s["id"] in a}) == 1, "同一录音条件簇"
    cs = v17.prompt_candidates(segs, n=4, seed=7)
    assert len({tuple(c["ids"]) for c in cs}) == len(cs)


def test_ref_health_flags_without_modifying():
    rng = np.random.default_rng(0); t = np.arange(10 * SR) / SR
    clean = (0.2 * np.sin(2 * np.pi * 150 * t) * (np.sin(2 * np.pi * .6 * t) > -.2)).astype(np.float32) + rng.normal(0, 5e-5, len(t)).astype(np.float32)
    noisy = clean + rng.normal(0, 0.004, len(t)).astype(np.float32); keep = noisy.copy()
    assert v17.ref_health(clean, SR)["flags"] == [] and "noisy" in v17.ref_health(noisy, SR)["flags"]
    assert np.array_equal(keep, noisy)
    n = 48000 * 8; W = np.fft.rfft(rng.normal(0, 0.05, n)); W[np.fft.rfftfreq(n, 1 / 48000) > 16000] *= 1e-3
    assert "lossy" in v17.ref_health(np.fft.irfft(W, n).astype(np.float32), 48000)["flags"]


def test_studio_best_of_n_and_honest_failure():
    calls = []

    def synth(text, seed, temperature, rep_penalty):
        calls.append(seed); k = len(calls)
        y = (0.2 * np.sin(2 * np.pi * 160 * np.arange(3 * SR) / SR)).astype(np.float32)
        if k <= 2: y[30000] += 0.6
        if k == 3: raise RuntimeError("OOM")
        return y
    c = v17.studio_render("你好", synth, n=4)["certificate"]
    assert c["status"] == "pass" and [x["level"] for x in c["candidates"]] == ["red", "red", "error", "green"]

    def allbad(text, seed, temperature, rep_penalty):
        y = (0.2 * np.sin(2 * np.pi * 160 * np.arange(3 * SR) / SR)).astype(np.float32); y[30000] += 0.6; return y
    r = v17.studio_render("坏", allbad, n=3, max_rounds=2)
    assert r["certificate"]["status"] == "best_effort" and r["pcm"] is not None and "未达标放行" in r["certificate"]["note"]
    r = v17.studio_render("崩", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("x")), n=2, max_rounds=1)
    assert r["certificate"]["status"] == "failed" and r["pcm"] is None
    a, b = v17.finalize_pcm16(np.full(1000, .5, np.float32), 1), v17.finalize_pcm16(np.full(1000, .5, np.float32), 1)
    assert np.array_equal(a, b) and a.dtype == np.int16


def test_router_champion_default_and_gate_required():
    R = v17.Router(os.path.join(tempfile.mkdtemp(), "d.json")); inst = ["voxcpm2", "indextts2"]
    assert R.engine_for("L") == "voxcpm2"
