_http = tp._http
SR = 24000


def poll_job(srv, jid, timeout=120):
    t0 = time.time()
    while time.time() - t0 < timeout:
        j = _http(srv, "GET", "/api/v17/jobs/" + jid)[1]["job"]
        if j["state"] != "running":
            return j
        time.sleep(0.4)
    raise AssertionError("导入超时")


def upload(srv, name, data, chunk=1_500_000, resume_probe=True):
    code, c, _ = _http(srv, "POST", "/api/v17/uploads?name=%s&size=%d&sha256=%s" % (urllib.parse.quote(name), len(data), hashlib.sha256(data).hexdigest()))
    assert code == 200 and c["ok"], c
    uid, off, probed = c["id"], 0, False
    while off < len(data):
        blk = data[off:off + chunk]
        code, r, _ = _http(srv, "PATCH", "/api/v17/uploads/%s?offset=%d&sha=%s" % (uid, off, hashlib.sha256(blk).hexdigest()), blk, timeout=60)
        assert code == 200, r
        if resume_probe and not probed and off > 0:                      # 模拟网络抖动:客户端把上一块又发了一次 → 服务器告知期望偏移
            code2, r2, _ = _http(srv, "PATCH", "/api/v17/uploads/%s?offset=%d" % (uid, off - chunk), data[off - chunk:off])
            assert code2 == 409 and r2["expected"] == r["offset"], (code2, r2)
            probed = True
        off = r["offset"]
    code, f, _ = _http(srv, "POST", "/api/v17/uploads/%s/finish" % uid, {})
    assert code == 200 and f["sha256"] == hashlib.sha256(data).hexdigest(), f
    return uid


