        worse = {"sim": [0.70, 0.71, 0.69, 0.70, 0.72, 0.70], "cer": [0.05] * 6, "defect_rate": [0] * 6, "red_defects": [0] * 6}
        better = {"sim": [0.84, 0.85, 0.83, 0.84, 0.86, 0.84], "cer": [0.05, 0.04, 0.05, 0.05, 0.04, 0.05], "defect_rate": [0] * 6, "red_defects": [0] * 6}
        assert _http(srv, "GET", "/api/libs/%s/v17" % lid)[1]["timeline"]["champion"] == "m_000"
        c1 = _http(srv, "POST", "/api/libs/%s/v17/candidates" % lid, {"recipe": "lora_incr"})[1]["version"]
        g = _http(srv, "POST", "/api/libs/%s/v17/gate" % lid, {"champion": base, "challenger": worse})[1]["result"]
        assert g["promote"] is False
        r = _http(srv, "POST", "/api/libs/%s/v17/models/%s/promote" % (lid, c1), {"champion": base, "challenger": worse, "load_ok": True, "trial_ok": True})[1]
        assert r["ok"] is False and _http(srv, "GET", "/api/libs/%s/v17" % lid)[1]["timeline"]["champion"] == "m_000", "更差候选必须被拒"
        r = _http(srv, "POST", "/api/libs/%s/v17/models/%s/promote" % (lid, c1), {"champion": base, "challenger": better, "load_ok": True, "trial_ok": False})[1]
        assert r["ok"] is False, "缺试合成不得晋升"
        r = _http(srv, "POST", "/api/libs/%s/v17/models/%s/promote" % (lid, c1), {"champion": base, "challenger": better, "load_ok": True, "trial_ok": True})[1]
