def run_turn_pcm(**env):
    srv = tg.Server(**env)
    try:
        srv.clone()
        r = asyncio.run(t13.collect(srv.port, tg.LONG, sid="v17"))
        assert r["done"] and r["chk"].verify_done(r["done"]["frames"], r["done"]["samples"])
        time.sleep(1.2)
        rep = json.load(urllib.request.urlopen(srv.url("/api/report"), timeout=10))
        return np.asarray(r["pcm"]).astype(np.int16), rep
    finally:
        srv.stop()


def test_defect_counters_and_golden_pcm_equal_when_off():
    pcm_on, rep_on = run_turn_pcm()
