FILES['v17.py'] = r'''# -*- coding: utf-8 -*-
"""
v17.py —— v17 增量模块「缺陷检测 · 不降级闸门 · 版本谱系 · 提示词搜索 · 参考体检 · Studio Best-of-N · 引擎路由」
只依赖 numpy(v15/v16 存在时复用其取证函数);网关与 GPU 进程共用;纯 CPU 逻辑,可在无 GPU 沙箱里单元测试。
每个子模块有独立开关,全部关闭 = v16 行为(本模块不改任何既有推理 / 后处理 / 实时通路的音频,PCM 逐样本一致):
    VC_V17=0                  总开关
    VC_V17_DEFECTS=0/1        缺陷检测器(NaN/削波/数字零段/click/真峰值/沙沙声(相对参考底噪)/块间台阶),只测量
    VC_V17_GATE=0/1           不降级闸门:非劣效 + 配对 bootstrap 显著提升(纯函数)
    VC_V17_LINEAGE=0/1        版本谱系:不可变版本 · 晋升 · 回滚 · 金丝雀自动回滚(只写 v17 命名空间,不改旧字段)
    VC_V17_INGEST=0/1         无时长限制入库:分块断点续传上传 + 录音流式分片落盘(.part → 校验 → 原子改名)
    VC_V17_PROMPT=0/1         提示词搜索:MMR(质量×声纹多样性)选 ≤20 秒子集,固定种子可复现
    VC_V17_REFHEALTH=0/1      参考体检:只给「建议」,绝不降噪、绝不改原件(只做 50Hz 零相位高通/直流保护的建议)
    VC_V17_STUDIO=0/1         Studio 模式:整句 Best-of-N + 缺陷检测择优 + 重试阶梯;Live 实时模式完全不动
    VC_V17_ROUTER=0/1         引擎路由:冠军 = VoxCPM2;挑战者必须过硬门槛 + 显著优于冠军才可成为某语音库默认
    VC_V17_UI=0/1             /v17 页面与 /api/v17/* 接口
    VC_V17_REC_UNLIMITED=0/1  快速克隆录音页去掉 1800 秒自动停止
诚实声明:本模块在 CPU 上用合成信号验证「逻辑与客观指标」;没有 GPU / 真机 / 人耳数据。
    「更像」「沙沙声更少」只能由 T4×2 真机实测 + /abx 盲测裁决;所有阈值是启发式、未校准;没有证据一律标注「未验证」。
"""
import hashlib
import json
import math
import os
import secrets
import threading
import time

import numpy as np

SR = 24000
VERSION = "v17.0"

try:  # 复用 v15 / v16 的取证函数;缺失则用本模块自带的最小实现
    import v15 as _v15
except Exception:  # noqa: BLE001
    _v15 = None
try:
    import v16 as _v16
except Exception:  # noqa: BLE001
    _v16 = None


# ───────────────────────── 开关 ─────────────────────────
def _flag(name, default="1"):
    return str(os.environ.get(name, default)).strip().lower() not in ("0", "false", "off", "no", "")


def on(name):
    return _flag("VC_V17") and _flag("VC_V17_" + name)


SWITCH_NAMES = ("DEFECTS", "GATE", "LINEAGE", "INGEST", "PROMPT", "REFHEALTH", "STUDIO", "ROUTER", "UI", "REC_UNLIMITED")


def switches():
    return {k: on(k) for k in SWITCH_NAMES}


def envf(name, default):
    try:
        return float(os.environ.get(name, default))
    except Exception:  # noqa: BLE001
        return float(default)


def _db(v, floor=1e-9):
    return 20.0 * math.log10(max(float(v), floor))


def to_float(pcm):
    a = np.asarray(pcm)
    if a.dtype.kind in "iu":
        return a.astype(np.float32) / 32768.0
    return a.astype(np.float32)


# ═════════════════════════ M1 缺陷检测器 ═════════════════════════
HF_ABS_WARN_DB = -58.0       # 与 v16 一致的绝对沙沙声告警线(启发式,未校准)
HF_REL_MARGIN_DB = 6.0       # H3:相对「参考自身底噪」允许多出 6 dB(启发式,未校准)
CLICK_RATIO = 10.0           # 二阶差分尖峰 / 局部平均 的倍数
CLICK_ABS = 0.04             # 二阶差分绝对下限(满量程 ±1)
STEP_DB = 12.0               # 20ms 窗 RMS 台阶阈值(自然起音会误报,所以只记黄色)
TRUE_PEAK_LIMIT_DB = -0.5

RED_KINDS = ("nan_inf", "clip", "zero_run", "click", "true_peak")
YELLOW_KINDS = ("hiss", "level_step", "dc")


def _uniform_mean(a, w):
    c = np.concatenate([[0.0], np.cumsum(a, dtype=np.float64)])
    half = w // 2
    idx = np.arange(len(a))
    lo = np.maximum(idx - half, 0)
    hi = np.minimum(idx + half + 1, len(a))
    return (c[hi] - c[lo]) / np.maximum(hi - lo, 1)


def find_clicks(x, sr=SR):
    """孤立尖峰(click/pop)检测,返回 [秒]。二阶差分 > max(CLICK_ABS, CLICK_RATIO × 局部平均);1.5ms 内合并为一次。"""
    x = np.asarray(x, np.float32)
    if len(x) < 64:
        return []
    d2 = np.abs(x[2:] - 2 * x[1:-1] + x[:-2]).astype(np.float64)
    loc = _uniform_mean(d2, max(int(0.010 * sr) | 1, 9))
    hit = np.where(d2 > np.maximum(CLICK_ABS, CLICK_RATIO * loc))[0]
    out, last = [], -10 ** 9
    gap = int(0.0015 * sr)
    for i in hit:
        if i - last > gap:
            out.append(round(float(i + 1) / sr, 4))
        last = i
    return out


def find_digital_zero_runs(x, sr=SR, min_ms=2.0):
    """语音内部的数字零段:≥ min_ms 的连续精确 0,且前后 20ms 都不是静音(排除开头/结尾/真停顿)。返回 [(秒, 毫秒)]。"""
    x = np.asarray(x, np.float32)
    n = len(x)
    z = np.concatenate([[0], (x == 0).astype(np.int8), [0]])
    e = np.diff(z)
    s, t = np.where(e == 1)[0], np.where(e == -1)[0]
    w = int(0.020 * sr)
    out = []
    for a, b in zip(s, t):
        if (b - a) < int(min_ms * 1e-3 * sr) or a < w or b + w > n:
            continue
        before = float(np.sqrt(np.mean(x[a - w:a] ** 2)))
        after = float(np.sqrt(np.mean(x[b:b + w] ** 2)))
        if before > 10 ** (-45 / 20) and after > 10 ** (-45 / 20):
            out.append((round(float(a) / sr, 4), round(float(b - a) * 1000.0 / sr, 1)))
    return out


def _true_peak_db(x):
    if _v15 is not None:
        try:
            return float(_v15.true_peak_db(x))
        except Exception:  # noqa: BLE001
            pass
    n = len(x)
    if n == 0:
        return -120.0
    X = np.fft.rfft(x)
    Y = np.zeros(n * 2 + 1, np.complex128)
    Y[: len(X)] = X
    y = np.fft.irfft(Y, n * 4) * 4.0
    return _db(np.abs(y).max())


def level_steps(x, sr=SR, win_ms=20.0, thr_db=STEP_DB):
    """相邻 20ms 窗 RMS 台阶(两窗都 > -40 dBFS 才算),返回 (最大台阶 dB, 超阈次数, 位置[秒])。"""
    w = int(win_ms * 1e-3 * sr)
    nw = len(x) // w
    if nw < 3:
        return 0.0, 0, []
    r = np.sqrt((np.asarray(x[: nw * w], np.float32).reshape(nw, w) ** 2).mean(axis=1))
    ok = (r[:-1] > 10 ** (-40 / 20)) & (r[1:] > 10 ** (-40 / 20))
    if not ok.any():
        return 0.0, 0, []
    st = np.abs(20 * np.log10(np.maximum(r[1:], 1e-9) / np.maximum(r[:-1], 1e-9)))
    st = np.where(ok, st, 0.0)
    pos = np.where(st > thr_db)[0]
    return round(float(st.max()), 1), int(len(pos)), [round(float((p + 1) * w) / sr, 3) for p in pos[:20]]


def detect_defects(pcm, sr=SR, ref_hf_db=None):
    """对一段输出做缺陷体检。返回 dict:level(green/yellow/red)/defects/events/metrics/score。
    红色(必须重试/不放行):NaN/Inf、削波、语音内数字零段、click、真峰值超限;
    黄色(提示):沙沙声(绝对线或相对参考底噪 +6dB)、块间台阶、直流偏移。score 越小越好,用于 Best-of-N 排序。"""
    x = to_float(pcm)
    n = len(x)
    rep = {"n": n, "seconds": round(n / float(sr), 2), "defects": [], "events": {}, "metrics": {}, "level": "green", "score": 0.0}
    if n < 480:
        rep["note"] = "太短,未分析"
        return rep
    bad = ~np.isfinite(x)
    if bad.any():
        rep["defects"].append({"kind": "nan_inf", "severity": "red", "detail": "NaN/Inf %d 样本" % int(bad.sum())})
        x = np.where(bad, 0.0, x).astype(np.float32)
    clip = int((np.abs(x) >= 0.999).sum())
    if clip:
        rep["defects"].append({"kind": "clip", "severity": "red", "detail": "削波 %d 样本" % clip})
    zr = find_digital_zero_runs(x, sr)
    if zr:
        rep["events"]["zero_runs"] = zr[:20]
        rep["defects"].append({"kind": "zero_run", "severity": "red", "detail": "语音内数字零段 %d 处" % len(zr)})
    ck = find_clicks(x, sr)
    if ck:
        rep["events"]["clicks"] = ck[:20]
        rep["defects"].append({"kind": "click", "severity": "red", "detail": "疑似 click %d 处(首个 %.3fs)" % (len(ck), ck[0])})
    tp = _true_peak_db(x)
    rep["metrics"]["true_peak_dbfs"] = round(tp, 2)
    if tp > TRUE_PEAK_LIMIT_DB:
        rep["defects"].append({"kind": "true_peak", "severity": "red", "detail": "真峰值 %.1f dBFS 超过 %.1f" % (tp, TRUE_PEAK_LIMIT_DB)})
    hf = None
    if _v16 is not None:
        try:
            hf = _v16.hf_noise_metrics(x, sr).get("hf_floor_dbfs")
        except Exception:  # noqa: BLE001
            hf = None
    rep["metrics"]["hf_floor_dbfs"] = hf
    if hf is not None:
        rel = ref_hf_db is not None and hf > float(ref_hf_db) + HF_REL_MARGIN_DB
        if hf > HF_ABS_WARN_DB or rel:
            why = "高于参考自身底噪 %.1f dB" % (hf - float(ref_hf_db)) if rel else "绝对底噪 %.0f dBFS/bin" % hf
            rep["defects"].append({"kind": "hiss", "severity": "yellow", "detail": "疑似沙沙声:%s(启发式,未校准)" % why})
    mx, cnt, pos = level_steps(x, sr)
    rep["metrics"]["max_level_step_db"] = mx
    if cnt:
        rep["events"]["level_steps"] = pos
        rep["defects"].append({"kind": "level_step", "severity": "yellow", "detail": "20ms 响度台阶 >%.0fdB 共 %d 处(含自然起音,未区分)" % (STEP_DB, cnt)})
    dc = float(x.mean())
    rep["metrics"]["dc"] = round(dc, 5)
    if abs(dc) > 0.01:
        rep["defects"].append({"kind": "dc", "severity": "yellow", "detail": "直流偏移 %.3f" % dc})
    score = 0.0
    for d in rep["defects"]:
        score += 100.0 if d["severity"] == "red" else 10.0
    if hf is not None:
        score += max(0.0, hf - (-80.0)) * 0.05
    rep["score"] = round(score, 3)
    sev = {d["severity"] for d in rep["defects"]}
    rep["level"] = "red" if "red" in sev else ("yellow" if "yellow" in sev else "green")
    return rep


# ═════════════════════════ M2 不降级闸门(非劣效 + 显著提升) ═════════════════════════
def paired_bootstrap(diffs, n_boot=2000, seed=0):
    """配对差值的 bootstrap:返回 (均值, 5% 分位, 95% 分位)。固定种子可复现。"""
    d = np.asarray(diffs, np.float64)
    if len(d) == 0:
        return 0.0, 0.0, 0.0
    rng = np.random.default_rng(seed)
    idx = rng.integers(0, len(d), size=(n_boot, len(d)))
    m = d[idx].mean(axis=1)
    return float(d.mean()), float(np.percentile(m, 5)), float(np.percentile(m, 95))


# metric -> (方向:+1 越大越好 / -1 越小越好, 非劣效容差, 是否主指标(可作为「显著提升」依据))
GATE_METRICS = {
    "sim": (+1, 0.005, True),        # 说话人相似度(多评估器均值);ε=0.005
    "sim2": (+1, 0.005, True),       # 第二评估器(ECAPA/CAM++);缺失则标注「未验证」
    "cer": (-1, 0.01, True),         # ASR 回读字错率
    "utmos": (+1, 0.10, True),
    "dnsmos": (+1, 0.10, False),
    "hf_floor_db": (-1, 1.0, False),  # 沙沙声:安静帧 6k+ 底噪(dBFS/bin),越低越好;H3 不得高于冠军 +1dB
    "defect_rate": (-1, 0.0, True),   # 每句是否含红色缺陷(0/1)
}
GATE_REQUIRED = ("sim", "cer", "defect_rate")   # 缺任何一项 = 未验证 = 不晋升(宁可不换)


def gate_decide(champion, challenger, min_n=5, n_boot=2000, seed=0, require=GATE_REQUIRED, red_cap=0):
    """不降级闸门。champion / challenger: {指标名: 等长序列(同一留出集、同一批种子逐句配对)}。
    规则(提示词1 §7.6/§9.1):
      ① 硬门槛:挑战者红色缺陷句数 ≤ red_cap(默认 0;H1/H2)——`red_defects` 序列(每句红色缺陷个数)可选;
      ② 非劣效:每个有数据的指标,配对差的 bootstrap 5% 下界(按方向统一为「越大越好」)必须 > -容差;
      ③ 显著提升:至少一个主指标的 5% 下界 > 0;
      ④ 必需指标缺失 → 「未验证」→ 不晋升。没有证据不宣称更好。
    返回 {promote, checks:[{name,status:pass|fail|unverified,detail}], reason}。"""
    checks = []
    ok_all, any_sig = True, False

    def add(name, status, detail):
        checks.append({"name": name, "status": status, "detail": detail})

    n_ref = None
    for m, (sgn, tol, primary) in GATE_METRICS.items():
        b, c = champion.get(m), challenger.get(m)
        if b is None or c is None:
            if m in require:
                add(m, "unverified", "缺少数据(必需指标),不晋升")
                ok_all = False
            else:
                add(m, "unverified", "缺少数据(可选指标,不参与裁决)")
            continue
        b, c = np.asarray(b, np.float64), np.asarray(c, np.float64)
        if len(b) != len(c) or len(b) < min_n:
            add(m, "unverified", "样本对数不足(<%d)或长度不一致" % min_n)
            if m in require:
                ok_all = False
            continue
        n_ref = len(b)
        d = (c - b) * sgn                                   # 统一成「越大越好」
        mean, lo, hi = paired_bootstrap(d, n_boot=n_boot, seed=seed)
        noninf = lo > -tol - 1e-12 if tol > 0 else (c.mean() <= b.mean() + 1e-12 if sgn < 0 else mean >= -1e-12)
        if not noninf:
            ok_all = False
            add(m, "fail", "劣于冠军:均值差 %.4f,5%%下界 %.4f(容差 %.4f)" % (mean, lo, tol))
        else:
            sig = bool(primary and lo > 0)
            any_sig = any_sig or sig
            add(m, "pass", "非劣效;均值差 %+.4f,5%%下界 %.4f%s" % (mean, lo, " · 显著提升" if sig else ""))
    rd = challenger.get("red_defects")
    if rd is not None:
        tot = int(np.sum(np.asarray(rd) > 0))
        if tot > red_cap:
            ok_all = False
            add("red_defects", "fail", "挑战者有 %d 句含红色缺陷(上限 %d)" % (tot, red_cap))
        else:
            add("red_defects", "pass", "红色缺陷句数 %d ≤ %d" % (tot, red_cap))
    else:
        add("red_defects", "unverified", "未提供逐句红色缺陷数")
    if not any_sig and ok_all:
        ok_all = False
        reason = "未提升:没有任何主指标显著优于冠军,保留冠军"
    elif not ok_all:
        bad = [c_["name"] for c_ in checks if c_["status"] in ("fail",)] or [c_["name"] for c_ in checks if c_["status"] == "unverified" and c_["name"] in require]
        reason = "未通过闸门:" + "、".join(bad)
    else:
        reason = "通过:全部非劣效且至少一个主指标显著提升"
    return {"promote": bool(ok_all), "checks": checks, "reason": reason, "n": n_ref}


# ═════════════════════════ M3 版本谱系 · 晋升 · 回滚 · 金丝雀 ═════════════════════════
def snapshot_sha(items):
    """数据快照哈希:按 id 排序的 (id, sha) 序列 → sha256。训练前冻结,版本记录它。"""
    h = hashlib.sha256()
    for k, v in sorted((str(a), str(b)) for a, b in items):
        h.update(("%s:%s\n" % (k, v)).encode("utf-8"))
    return h.hexdigest()


def fixed_seed(*parts):
    """固定种子(回滚后同输入逐样本一致的前提)。"""
    h = hashlib.sha256("|".join(str(p) for p in parts).encode("utf-8")).digest()
    return int.from_bytes(h[:4], "big")


class Lineage:
    """每个语音库一份 v17 版本谱系(JSON,原子写)。版本不可变:只增不改;旧版本永不覆盖;可随时回滚。
    版本 0 = 旧库迁移出的冠军(兼容 v16 数据,旧字段一个都不动)。"""

    def __init__(self, path):
        self.path = str(path)
        self.lock = threading.RLock()
        self.d = {"schema": 1, "champion": None, "versions": {}, "events": [], "consent": None}
        if os.path.exists(self.path):
            try:
                self.d = json.load(open(self.path, "r", encoding="utf-8"))
            except Exception:  # noqa: BLE001
                bak = self.path + ".corrupt.%d" % int(time.time())
                os.replace(self.path, bak)               # 损坏文件改名保留,绝不删除用户数据
        else:
            self.d["created_at"] = time.strftime("%FT%T")

    # --- 内部 ---
    def _save(self):
        tmp = self.path + ".part"
        os.makedirs(os.path.dirname(self.path) or ".", exist_ok=True)
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(self.d, f, ensure_ascii=False, indent=1)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, self.path)

    def _ev(self, kind, **kw):
        self.d["events"].append(dict(kw, kind=kind, at=time.strftime("%FT%T")))
        self.d["events"] = self.d["events"][-500:]

    # --- 同意 / 迁移 ---
    def set_consent(self, owner_or_authorized, note=""):
        with self.lock:
            self.d["consent"] = {"owner_or_authorized": bool(owner_or_authorized), "at": time.strftime("%FT%T"), "note": str(note)[:200]}
            self._save()

    def ensure_v0(self, engine="voxcpm2", snapshot="", meta=None):
        """旧库首次进入 v17:建「版本 0」并设为冠军(幂等)。"""
        with self.lock:
            if "m_000" not in self.d["versions"]:
                self.d["versions"]["m_000"] = {"id": "m_000", "parent": None, "engine": engine, "recipe": "v16-legacy", "snapshot": snapshot,
                                               "metrics": {}, "status": "champion", "created_at": time.strftime("%FT%T"), "meta": dict(meta or {}),
                                               "canary": {"uses": 0, "bad": 0}}
                self.d["champion"] = "m_000"
                self._ev("migrate_v0", version="m_000")
                self._save()
            return self.d["versions"]["m_000"]

    # --- 版本 ---
    def add_candidate(self, parent=None, engine="voxcpm2", recipe="lora", snapshot="", metrics=None, params=None):
        with self.lock:
            if parent is None:
                parent = self.d["champion"]
            if parent is not None and parent not in self.d["versions"]:
                raise KeyError("父版本不存在: %s" % parent)
            vid = "m_%03d" % len(self.d["versions"])
            self.d["versions"][vid] = {"id": vid, "parent": parent, "engine": engine, "recipe": recipe, "snapshot": snapshot, "metrics": dict(metrics or {}),
                                       "params": dict(params or {}), "status": "candidate", "created_at": time.strftime("%FT%T"), "canary": {"uses": 0, "bad": 0}}
            self._ev("candidate", version=vid, parent=parent)
            self._save()
            return vid

    def champion(self):
        with self.lock:
            return self.d["champion"]

    def promote(self, vid, gate_result, load_ok=False, trial_ok=False, force_reason=None):
        """三项证据才晋升:闸门通过 + 成功加载 + 试合成通过缺陷检测(沿用 v10/v16)。force 需要书面理由并记录。"""
        with self.lock:
            v = self.d["versions"].get(vid)
            if v is None:
                return {"ok": False, "reason": "版本不存在"}
            if v["status"] == "champion":
                return {"ok": True, "reason": "已是冠军", "champion": vid}
            gate_ok = bool(gate_result and gate_result.get("promote"))
            if not (gate_ok and load_ok and trial_ok):
                if not (force_reason and str(force_reason).strip()):
                    miss = [n for n, ok in (("闸门", gate_ok), ("加载", load_ok), ("试合成", trial_ok)) if not ok]
                    self._ev("promote_refused", version=vid, missing=miss)
                    self._save()
                    return {"ok": False, "reason": "证据不足,保留冠军:缺 " + "、".join(miss), "champion": self.d["champion"]}
            old = self.d["champion"]
            if old and old in self.d["versions"]:
                self.d["versions"][old]["status"] = "retired"
            v["status"] = "champion"
            v["promoted_at"] = time.strftime("%FT%T")
            v["promote_basis"] = {"gate": gate_ok, "load": bool(load_ok), "trial": bool(trial_ok), "forced": bool(force_reason), "force_reason": (str(force_reason)[:200] if force_reason else None)}
            self.d["champion"] = vid
            self._ev("promote", version=vid, previous=old)
            self._save()
            return {"ok": True, "champion": vid, "previous": old}

    def rollback(self, to=None, reason="manual"):
        """回滚:默认回到冠军的父版本;被回滚的版本标记 rolled_back(保留,不删除)。"""
        with self.lock:
            cur = self.d["champion"]
            tgt = to or (self.d["versions"].get(cur, {}) or {}).get("parent")
            if not tgt or tgt not in self.d["versions"] or tgt == cur:
                return {"ok": False, "reason": "没有可回滚的目标", "champion": cur}
            if cur in self.d["versions"]:
                self.d["versions"][cur]["status"] = "rolled_back"
            self.d["versions"][tgt]["status"] = "champion"
            self.d["champion"] = tgt
            self._ev("rollback", from_=cur, to=tgt, reason=str(reason)[:200])
            self._save()
            return {"ok": True, "champion": tgt, "from": cur}

    def canary(self, ok, min_uses=20, max_bad_rate=0.10):
        """金丝雀:冠军晋升后的真实使用结果。达到 min_uses 且坏率 > max_bad_rate 自动回滚到父版本。"""
        with self.lock:
            cur = self.d["champion"]
            v = self.d["versions"].get(cur)
            if v is None or v.get("parent") is None:
                return {"rolled_back": False}
            c = v["canary"]
            c["uses"] += 1
            c["bad"] += 0 if ok else 1
            if c["uses"] >= min_uses and c["bad"] / float(c["uses"]) > max_bad_rate:
                r = self.rollback(reason="canary bad_rate=%.2f" % (c["bad"] / c["uses"]))
                r["rolled_back"] = bool(r.get("ok"))
                return r
            self._save()
            return {"rolled_back": False, "uses": c["uses"], "bad": c["bad"]}

    def timeline(self):
        with self.lock:
            return {"champion": self.d["champion"], "versions": [dict(v) for _, v in sorted(self.d["versions"].items())], "events": list(self.d["events"][-50:]), "consent": self.d.get("consent")}


def snapshot_backup(src_path, backup_dir):
    """旧语音库首次迁移前:备份为只读快照(提示词1 §9.2)。已存在则不重复备份。返回备份路径或 None。"""
    import shutil
    if not os.path.exists(src_path):
        return None
    os.makedirs(backup_dir, exist_ok=True)
    dst = os.path.join(backup_dir, os.path.basename(src_path) + ".v16.bak")
    if os.path.exists(dst):
        return dst
    shutil.copy2(src_path, dst)
    os.chmod(dst, 0o444)
    return dst


# ═════════════════════════ M4 提示词搜索(MMR:质量 × 声纹多样性,同录音条件簇) ═════════════════════════
def _cos(a, b):
    a, b = np.asarray(a, np.float64), np.asarray(b, np.float64)
    d = float(np.linalg.norm(a) * np.linalg.norm(b))
    return float(a @ b) / d if d > 0 else 0.0


def mmr_select(segments, max_total_s=20.0, max_k=6, lam=0.7, min_quality=50.0, seed=0, cluster=None):
    """从库里挑 ≤ max_total_s 秒的提示子集。segments: [{id, seconds, quality(0~100), emb(可选), cond(录音条件簇,可选), enabled, verified}]。
    仅用「已启用 + 已核对 + 质量达线」;若有 cond,只在总质量最高的那个簇里选(避免把不同麦克风/房间硬拼)。
    注意:20 秒只是「推理时放进模型的提示窗口」,不限制入库与训练。固定 seed → 结果可复现(并列时用稳定哈希破平)。"""
    pool = [s for s in segments if s.get("enabled", True) and s.get("verified", True) and float(s.get("quality", 0)) >= min_quality and float(s.get("seconds", 0)) > 0.5]
    if not pool:
        return []
    if cluster is None and any(s.get("cond") for s in pool):
        tot = {}
        for s in pool:
            tot[s.get("cond")] = tot.get(s.get("cond"), 0.0) + float(s["quality"]) * float(s["seconds"])
        cluster = max(sorted(tot, key=str), key=lambda k: tot[k])
    if cluster is not None:
        pool = [s for s in pool if s.get("cond") == cluster] or pool
    chosen, total = [], 0.0
    qmax = max(float(s["quality"]) for s in pool) or 1.0

    def tb(s):
        return fixed_seed(seed, s["id"]) / 4294967296.0 * 1e-6

    rest = list(pool)
    while rest and len(chosen) < max_k:
        best, bs = None, -1e18
        for s in rest:
            if total + float(s["seconds"]) > max_total_s + 1e-9:
                continue
            div = 0.0
            if chosen and s.get("emb") is not None:
                sims = [_cos(s["emb"], c["emb"]) for c in chosen if c.get("emb") is not None]
                div = max(sims) if sims else 0.0
            sc = lam * float(s["quality"]) / qmax - (1 - lam) * div + tb(s)
            if sc > bs:
                best, bs = s, sc
        if best is None:
            break
        chosen.append(best)
        total += float(best["seconds"])
        rest.remove(best)
    return [s["id"] for s in chosen]


def prompt_candidates(segments, n=4, max_total_s=20.0, seed=0):
    """生成 n 个互不相同的候选子集(不同 λ),交给真合成 + 打分后择优;去重,顺序固定。"""
    outs, seen = [], set()
    for lam in (0.7, 0.9, 0.5, 0.3, 1.0, 0.1):
        ids = tuple(mmr_select(segments, max_total_s=max_total_s, lam=lam, seed=seed))
        if ids and ids not in seen:
            seen.add(ids)
            outs.append({"ids": list(ids), "lam": lam})
        if len(outs) >= n:
            break
    return outs


def prompt_bank_key(ids, texts_sha=""):
    return hashlib.sha256(("|".join(sorted(map(str, ids))) + "#" + texts_sha).encode("utf-8")).hexdigest()[:16]


def pick_best_prompt(cands, scores):
    """scores 越大越好;并列取靠前者(稳定)。返回 (索引, 候选)。"""
    if not cands or len(cands) != len(scores):
        return None, None
    i = int(np.argmax(np.asarray(scores, np.float64)))
    return i, cands[i]


# ═════════════════════════ M5 参考体检(只给建议,绝不降噪、绝不改原件) ═════════════════════════
def ref_health(x, sr):
    """对一条参考素材体检并给出「建议」。不修改音频。
    指标:带宽(99.9% 能量截止)、有损编码痕迹(≥32k 采样率时 16k 以上断崖)、削波占比、直流、安静帧 HF 底噪、SNR 估计。"""
    x = to_float(x)
    n = len(x)
    out = {"seconds": round(n / float(sr), 2), "flags": [], "advice": [], "metrics": {}}
    if n < sr // 2:
        out["flags"].append("too_short")
        out["advice"].append("素材不足 0.5 秒,不入提示池")
        return out
    out["metrics"]["clip_frac"] = round(float((np.abs(x) >= 0.999).mean()), 5)
    out["metrics"]["dc"] = round(float(x.mean()), 5)
    seg = x[: min(n, 60 * sr)]
    nfft = 4096
    m = len(seg) // nfft
    if m >= 1:
        sp = (np.abs(np.fft.rfft(seg[: m * nfft].reshape(m, nfft) * np.hanning(nfft), axis=1)) ** 2).mean(axis=0)
        cum = np.cumsum(sp) / max(sp.sum(), 1e-20)
        bw = float(np.searchsorted(cum, 0.999)) / (len(sp) - 1) * sr / 2
        out["metrics"]["bandwidth_hz"] = round(bw, 0)
        if sr >= 32000:
            f = np.fft.rfftfreq(nfft, 1.0 / sr)
            mid = sp[(f >= 12000) & (f < 15500)].mean()
            hi = sp[(f >= 16500)].mean() if (f >= 16500).any() else mid
            cliff = 10 * math.log10(max(hi, 1e-20) / max(mid, 1e-20))
            out["metrics"]["cliff_16k_db"] = round(cliff, 1)
            if cliff < -35:
                out["flags"].append("lossy")
                out["advice"].append("疑似有损来源(webm/mp3/m4a 的 16k 以上断崖):可用,但优先选无损/更干净的素材")
    if _v16 is not None:
        try:
            hf = _v16.hf_noise_metrics(x, sr)["hf_floor_dbfs"]
        except Exception:  # noqa: BLE001
            hf = None
        out["metrics"]["hf_floor_dbfs"] = hf
        if hf is not None and hf > -62.0:
            out["flags"].append("noisy")
            out["advice"].append("安静处高频底噪偏高(%.0f dBFS/bin):ICL 会把底噪当音色复制。建议在安静环境重录;不要对它做激进降噪(会磨平音色)" % hf)
    fr = 480
    nf = n // fr
    r = np.sqrt((x[: nf * fr].reshape(nf, fr) ** 2).mean(axis=1))
    if nf >= 10:
        sig = float(np.percentile(r, 90))
        flo = float(np.percentile(r, 10))
        snr = _db(sig) - _db(flo)
        out["metrics"]["snr_est_db"] = round(snr, 1)
        if snr < 25:
            out["flags"].append("low_snr")
            out["advice"].append("信噪比估计偏低(%.0f dB):建议换更安静的片段" % snr)
    if out["metrics"]["clip_frac"] > 0.001:
        out["flags"].append("clipped")
        out["advice"].append("录音有削波:请降低麦克风增益重录")
    if abs(out["metrics"]["dc"]) > 0.01:
        out["flags"].append("dc")
        out["advice"].append("直流偏移:入库时仅做 50Hz 零相位高通保护(v15 既有)")
    pen = {"too_short": 100, "lossy": 10, "noisy": 25, "low_snr": 15, "clipped": 30, "dc": 5}
    out["score"] = max(0, 100 - sum(pen.get(k, 0) for k in out["flags"]))
    return out


# ═════════════════════════ M6 Studio 模式:整句 Best-of-N + 缺陷检测择优 + 重试阶梯 ═════════════════════════
def finalize_pcm16(y, seed=0, dither=True):
    """全程 float32,只在最后量化一次,TPDF 抖动(±1 LSB)。"""
    y = np.nan_to_num(np.asarray(y, np.float32), nan=0.0, posinf=0.0, neginf=0.0)
    if dither:
        rng = np.random.default_rng(seed)
        y = y + ((rng.random(len(y)) - rng.random(len(y))) / 32768.0).astype(np.float32)
    return np.clip(np.round(y * 32768.0), -32768, 32767).astype(np.int16)


def retry_ladder(seed=0, temperature=0.9, rep_penalty=1.05, n=4):
    """重试阶梯(沿用 v13/v14 思路):换种子 → 降温 → 提高重复惩罚。"""
    out = []
    for i in range(n):
        out.append({"seed": fixed_seed("studio", seed, i), "temperature": round(max(0.5, temperature - 0.08 * max(0, i - 1)), 3),
                    "rep_penalty": round(rep_penalty + (0.05 if i >= 3 else 0.0), 3)})
    return out


def studio_render(text, synth_fn, n=4, ref_hf_db=None, sim_fn=None, cer_fn=None, base=None, seed=0, budget_s=None, sr=SR, max_rounds=2):
    """整句非流式渲染并择优。synth_fn(text, seed=, temperature=, rep_penalty=) → float32/int16 PCM(可抛异常)。
    打分 total = 缺陷分 − 50×SIM + 100×CER(越小越好);红色缺陷候选永远排在无红色候选之后。
    全部候选都有红色缺陷 → 继续下一轮阶梯;耗尽后选分最小者并如实标注「未达标放行」,绝不静默放行。
    Live 实时模式不经过这里(所以 TTFA/欠载不受影响)。"""
    t0 = time.time()
    base = dict(base or {})
    cands, chosen = [], None
    for rnd in range(max_rounds):
        ladder = retry_ladder(seed=seed + rnd * 977, temperature=base.get("temperature", 0.9), rep_penalty=base.get("rep_penalty", 1.05), n=n)
        for p in ladder:
            if budget_s is not None and time.time() - t0 > budget_s and cands:
                break
            c = {"round": rnd, "seed": p["seed"], "temperature": p["temperature"], "rep_penalty": p["rep_penalty"]}
            try:
                y = to_float(synth_fn(text, seed=p["seed"], temperature=p["temperature"], rep_penalty=p["rep_penalty"]))
                if len(y) == 0:
                    raise ValueError("空音频")
                rep = detect_defects(y, sr, ref_hf_db=ref_hf_db)
                c.update(level=rep["level"], defects=[d["kind"] for d in rep["defects"]], defect_score=rep["score"], seconds=rep["seconds"])
                tot = rep["score"]
                if sim_fn is not None:
                    c["sim"] = float(sim_fn(y)); tot -= 50.0 * c["sim"]
                if cer_fn is not None:
                    c["cer"] = float(cer_fn(y, text)); tot += 100.0 * c["cer"]
                c["total"] = round(tot, 4)
                c["_y"] = y
            except Exception as e:  # noqa: BLE001
                c.update(level="error", error=str(e)[:120], total=1e9)
            cands.append(c)
        ok = [c for c in cands if c.get("level") in ("green", "yellow")]
        if ok:
            chosen = min(ok, key=lambda c: (c["total"], c["seed"]))
            break
    status = "pass" if chosen is not None else "best_effort"
    if chosen is None:
        valid = [c for c in cands if "_y" in c]
        chosen = min(valid, key=lambda c: (c["total"], c["seed"])) if valid else None
        if chosen is None:
            status = "failed"
    cert = {"status": status, "n_evaluated": len(cands), "elapsed_s": round(time.time() - t0, 3), "validated": "沙箱信号层检测;真实音质/相似度未验证(需真机 + /abx)",
            "candidates": [{k: v for k, v in c.items() if k != "_y"} for c in cands],
            "chosen_seed": chosen["seed"] if chosen else None,
            "note": {"pass": "已选出无红色缺陷的最优候选", "best_effort": "未达标放行:所有候选都含红色缺陷,已选缺陷最轻者,请人工试听或重试", "failed": "全部候选合成失败,无音频可放行"}[status]}
    pcm = chosen["_y"] if chosen else None
    return {"pcm": pcm, "certificate": cert}


# ═════════════════════════ M7 引擎适配 + 路由(冠军 / 挑战者制度) ═════════════════════════
ENGINES = {
    "voxcpm2": {"name": "VoxCPM2(openbmb/VoxCPM2 · 2B · 48kHz)", "champion": True, "license": "Apache-2.0(以官方仓库为准,商用前请核实)", "installed": True, "validated": "v19 唯一主引擎;适配层沙箱已验证(假模型),真机音质/速度【未验证】"},
    "indextts2": {"name": "IndexTTS2", "champion": False, "license": "[待核]", "installed": False, "validated": "未验证(沙箱无 GPU,未安装)"},
    "cosyvoice3": {"name": "CosyVoice3-0.5B", "champion": False, "license": "[待核]", "installed": False, "validated": "未验证"},
    "f5": {"name": "F5-TTS", "champion": False, "license": "[待核]", "installed": False, "validated": "未验证"},
    "fish_s2": {"name": "Fish Audio S2", "champion": False, "license": "研究/非商用,需核对", "installed": False, "validated": "未验证"},
}
CHAMPION_ENGINE = "voxcpm2"


class EngineAdapter:
    """统一引擎接口(每个引擎应在独立虚拟环境/独立进程里运行,用 JSON 行协议通信)。输出一律 float32 单声道 + 真实采样率。"""
    name = "base"

    def load(self):  # noqa: D401
        raise NotImplementedError

    def make_speaker_state(self, ref_audio, ref_text):
        raise NotImplementedError

    def synthesize(self, text, state, seed=0, **kw):
        raise NotImplementedError

    def release(self):
        pass


class SubprocessEngine(EngineAdapter):
    """JSON 行协议适配器:子进程读一行 JSON 请求、写一行 JSON 响应({"pcm_b64","sr"} 或 {"error"})。独立 venv 避免 torch/transformers 版本冲突。"""

    def __init__(self, cmd, timeout=120):
        import subprocess
        self.cmd, self.timeout, self.proc, self._sp = cmd, timeout, None, subprocess
        self.lock = threading.Lock()

    def load(self):
        self.proc = self._sp.Popen(self.cmd, stdin=self._sp.PIPE, stdout=self._sp.PIPE, stderr=self._sp.DEVNULL, text=True, bufsize=1)
        return self

    def _call(self, obj):
        import base64
        with self.lock:
            self.proc.stdin.write(json.dumps(obj, ensure_ascii=False) + "\n")
            self.proc.stdin.flush()
            line = self.proc.stdout.readline()
        if not line:
            raise RuntimeError("引擎进程已退出")
        r = json.loads(line)
        if "error" in r:
            raise RuntimeError(r["error"])
        return np.frombuffer(base64.b64decode(r["pcm_b64"]), np.float32).copy(), int(r["sr"])

    def make_speaker_state(self, ref_audio, ref_text):
        return {"ref_text": ref_text, "ref_len": int(len(ref_audio))}

    def synthesize(self, text, state, seed=0, **kw):
        return self._call({"op": "synth", "text": text, "seed": int(seed), "state": state, "kw": kw})

    def release(self):
        try:
            if self.proc:
                self.proc.stdin.close()
                self.proc.terminate()
        except Exception:  # noqa: BLE001
            pass


class Router:
    """每个语音库一份 decision(冠军引擎 + 依据)。挑战者必须:已安装 + 闸门 promote=True,才可成为默认;否则永远是 VoxCPM2 冠军。"""

    def __init__(self, path):
        self.path = str(path)
        self.lock = threading.Lock()
        self.d = {}
        if os.path.exists(self.path):
            try:
                self.d = json.load(open(self.path, "r", encoding="utf-8"))
            except Exception:  # noqa: BLE001
                self.d = {}

    def _save(self):
        os.makedirs(os.path.dirname(self.path) or ".", exist_ok=True)
        tmp = self.path + ".part"
        json.dump(self.d, open(tmp, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        os.replace(tmp, self.path)

    def engine_for(self, lib_id, requested=None, installed=None):
        installed = set(installed) if installed is not None else {k for k, v in ENGINES.items() if v["installed"]}
        rec = self.d.get(lib_id) or {}
        eng = requested or rec.get("engine") or CHAMPION_ENGINE
        if eng != CHAMPION_ENGINE:
            ok = (rec.get("engine") == eng and rec.get("gate_promote") is True) or False
            if eng not in installed or (requested is None and not ok):
                return CHAMPION_ENGINE
            if requested is not None and not ok and not rec.get("manual_override"):
                return CHAMPION_ENGINE
        return eng

    def set_engine(self, lib_id, engine, gate_result, report_ref="", installed=None):
        installed = set(installed) if installed is not None else {k for k, v in ENGINES.items() if v["installed"]}
        with self.lock:
            if engine == CHAMPION_ENGINE:
                self.d[lib_id] = {"engine": CHAMPION_ENGINE, "gate_promote": True, "at": time.strftime("%FT%T"), "evidence": "冠军默认"}
                self._save()
                return {"ok": True, "engine": CHAMPION_ENGINE}
            if engine not in ENGINES or engine not in installed:
                return {"ok": False, "reason": "引擎未安装/未验证,保持冠军 VoxCPM2"}
            if not (gate_result and gate_result.get("promote")):
                return {"ok": False, "reason": "未通过闸门(硬门槛 + 显著优于冠军),保持冠军 VoxCPM2"}
            self.d[lib_id] = {"engine": engine, "gate_promote": True, "at": time.strftime("%FT%T"), "evidence": report_ref or "gate", "gate": gate_result.get("reason")}
            self._save()
            return {"ok": True, "engine": engine}


# ═════════════════════════ 计数器(诊断面板用,线程安全) ═════════════════════════
class Counters:
    KEYS = ("turns_checked", "turns_red", "turns_yellow", "turns_green", "last_defects", "gate_runs", "gate_rejects", "gate_promotes",
            "uploads_done", "rec_done", "imports", "import_segments", "import_rejected", "studio_renders", "studio_best_effort",
            "studio_failed", "prompt_searches", "lineage_promotes", "lineage_rollbacks", "router_refusals")

    def __init__(self):
        self.lock = threading.Lock()
        self.d = {k: 0 for k in self.KEYS}
        self.d["last_defects"] = []
        self.d["last_hf_dbfs"] = None

    def inc(self, k, n=1):
        with self.lock:
            self.d[k] = self.d.get(k, 0) + n

    def add_turn(self, rep):
        with self.lock:
            self.d["turns_checked"] += 1
            self.d["turns_" + rep.get("level", "green")] = self.d.get("turns_" + rep.get("level", "green"), 0) + 1
            self.d["last_defects"] = [x["detail"] for x in rep.get("defects", [])][:6]
            self.d["last_hf_dbfs"] = (rep.get("metrics") or {}).get("hf_floor_dbfs")

    def snapshot(self):
        with self.lock:
            return dict(self.d)
'''

