import numpy as np
import vox_audio as va

OK = []
def T(f):
    OK.append(f); return f

@T
def test_decimator_chunked_equals_oneshot():
    rng = np.random.default_rng(1); x = (rng.standard_normal(48000 * 2) * 0.1).astype(np.float32)
    one = va.StreamDecimator().process(x); one = np.concatenate([one, va.StreamDecimator().process(x)[:0]])
    d1 = va.StreamDecimator(); full = np.concatenate([d1.process(x), d1.flush()])
    d2 = va.StreamDecimator(); parts = []; i = 0
    for n in [7680, 1, 3, 7680, 4097, 7680, 100, 13]:           # 故意用奇数/极小块,检验相位与状态
        parts.append(d2.process(x[i:i + n])); i += n
    parts.append(d2.process(x[i:])); parts.append(d2.flush())
    ch = np.concatenate(parts)
    assert len(full) == len(ch) == math.ceil(len(x) / 2), (len(full), len(ch))
    assert np.max(np.abs(full - ch)) < 1e-6, np.max(np.abs(full - ch))

@T
def test_decimator_tone_gain_and_alias():
    t = np.arange(48000) / 48000.0
    for f, lo, hi in [(300, -0.1, 0.1), (1000, -0.1, 0.1), (4000, -0.1, 0.1), (8000, -0.2, 0.2)]:
        d = va.StreamDecimator(); y = np.concatenate([d.process(np.sin(2 * np.pi * f * t).astype(np.float32)), d.flush()])
        g = 20 * np.log10(np.sqrt(np.mean(y[2000:-2000] ** 2)) / (1 / np.sqrt(2)))
        assert lo < g < hi, (f, g)
    for f in (15000, 20000):                                     # 高于 12k 的成分必须被滤掉,不得折叠成可闻的混叠
        d = va.StreamDecimator(); y = np.concatenate([d.process(np.sin(2 * np.pi * f * t).astype(np.float32)), d.flush()])
        g = 20 * np.log10(np.sqrt(np.mean(y[2000:-2000] ** 2)) / (1 / np.sqrt(2)) + 1e-12)
        assert g < -60, (f, g)

@T
def test_decimator_no_boundary_click():
    t = np.arange(48000 * 3) / 48000.0; x = (0.3 * np.sin(2 * np.pi * 220 * t)).astype(np.float32)
    d = va.StreamDecimator(); outs = []
