def lookup_iso226_contour(freq_hz: float) -> Dict[str, float]:
    f = float(freq_hz)
    best = min(ISO226_LOUDNESS_GRID_48K, key=lambda r: abs(r['freq_hz'] - f))
    return dict(best)


def lookup_eer_operating_point(cosine_val: float) -> Dict[str, float]:
    c = float(cosine_val)
    best = min(SPEAKER_EER_CALIBRATION_GRID, key=lambda r: abs(r['cosine_threshold'] - c))
    return dict(best)


def dsp_calibration_summary() -> Dict[str, int]:
    return {
        "iso226_points": len(ISO226_LOUDNESS_GRID_48K),
        "eer_grid_points": len(SPEAKER_EER_CALIBRATION_GRID),
    }
'''

FILES['v20_frontend.py'] = r'''# -*- coding: utf-8 -*-
"""
v20_frontend.py —— S8 / M8 工业级文本前端规范化引擎

功能:
  1. 数字/日期/时间/金额/百分比/分数/电话串号/科学单位(kHz/dB/ms/GB)口语化展开
  2. 网址/邮箱可读化(避免直接删掉 URL 导致语义断裂,也支持静默剥离模式)
  3. 常见中文多音字词典上下文消歧与韵律边界标记
  4. 括号语义拆分(Live 通道剥离舞台指令括号,绝不误读;Studio 通道合成为 VoxCPM2 官方风格前缀)
  5. 独立开关 VC_V20_FRONTEND(关闭时退回 vox_audio.sanitize_text,确保黄金基线逐样本一致)
"""
import os
import re
from vox_audio import sanitize_text, split_style_brackets
from v20_lexicon_zh_en import expand_domain_terms, lookup_polyphone_phrase, lexicon_stats

_DIGITS_ZH = "零一二三四五六七八九"
_UNITS_SMALL = ["", "十", "百", "千"]


def _int_to_zh(n: int) -> str:
    if n < 0:
        return "负" + _int_to_zh(-n)
    if n < 10:
        return _DIGITS_ZH[n]
    if n < 20:
        return "十" + ("" if n == 10 else _DIGITS_ZH[n % 10])
    if n < 10000:
        s = str(n)
        out = []
        zero_pending = False
        L = len(s)
        for i, ch in enumerate(s):
            d = int(ch)
            pos = L - 1 - i
            if d == 0:
                zero_pending = True
            else:
                if zero_pending:
                    out.append("零")
                    zero_pending = False
                out.append(_DIGITS_ZH[d] + _UNITS_SMALL[pos])
        res = "".join(out)
        return res[1:] if res.startswith("一十") and len(res) <= 3 else res
    if n < 100000000:
        hi, lo = divmod(n, 10000)
        if lo == 0:
            return _int_to_zh(hi) + "万"
        if lo < 1000:
            return _int_to_zh(hi) + "万零" + _int_to_zh(lo)
        return _int_to_zh(hi) + "万" + _int_to_zh(lo)
    hi, lo = divmod(n, 100000000)
    if lo == 0:
        return _int_to_zh(hi) + "亿"
    if lo < 10000000:
        return _int_to_zh(hi) + "亿零" + _int_to_zh(lo)
    return _int_to_zh(hi) + "亿" + _int_to_zh(lo)


def _digits_serial_zh(s: str, telecom: bool = False) -> str:
    table = "零幺二三四五六七八九" if telecom else _DIGITS_ZH
    return "".join(table[int(ch)] if ch.isdigit() else ch for ch in s)


def _num_str_to_zh(s: str) -> str:
    s = s.strip()
    if not s:
        return s
    neg = s.startswith("-")
    if neg or s.startswith("+"):
        s = s[1:]
    if "." in s:
        ip, fp = s.split(".", 1)
        i_zh = _int_to_zh(int(ip)) if ip.isdigit() else _digits_serial_zh(ip)
        f_zh = _digits_serial_zh(fp)
        return ("负" if neg else "") + f"{i_zh}点{f_zh}"
    if s.isdigit():
        if len(s) >= 7 or (len(s) > 1 and s.startswith("0")):
            return _digits_serial_zh(s)
        return ("负" if neg else "") + _int_to_zh(int(s))
    return s


_UNIT_MAP = [
    (re.compile(r"(\d+(?:\.\d+)?)\s*kHz\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "千赫兹"),
    (re.compile(r"(\d+(?:\.\d+)?)\s*Hz\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "赫兹"),
    (re.compile(r"(-?\d+(?:\.\d+)?)\s*dB(?:FS|TP)?\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "分贝"),
    (re.compile(r"(-?\d+(?:\.\d+)?)\s*LUFS\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "响度单位"),
    (re.compile(r"(\d+(?:\.\d+)?)\s*ms\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "毫秒"),
    (re.compile(r"(\d+(?:\.\d+)?)\s*GB\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "吉字节"),
    (re.compile(r"(\d+(?:\.\d+)?)\s*MB\b", re.I), lambda m: _num_str_to_zh(m.group(1)) + "兆字节"),
]

_POLYPHONE_LEXICON = {
    "银行": "银hang2",
    "行业": "hang2业",
    "行走": "xing2走",
    "重庆": "chong2庆",
    "重要": "zhong4要",
    "重新": "chong2新",
    "音乐": "音yue4",
    "快乐": "快le4",
    "长大": "zhang3大",
    "长度": "chang2度",
    "数字": "shu4字",
    "数落": "shu3落",
    "处理": "chu3理",
    "到处": "到chu4",
    "朝阳": "zhao1阳",
    "朝向": "chao2向",
    "弹琴": "tan2琴",
    "子弹": "子dan4",
}


def normalize_numbers_zh(text: str, keep_url_spoken: bool = True) -> str:
    """将日期、时间、金额、百分比、分数、电话号码、技术单位及数字规范化为自然中文口语。"""
    t = text or ""
    if not t:
        return ""

    # 1. URLs
    def _url_sub(m):
        if not keep_url_spoken:
            return ""
        u = re.sub(r"^https?://", "", m.group(0)).rstrip("/")
        u = u.replace(".", "点").replace("/", "斜杠").replace("-", "杠").replace("_", "下划线")
        return u

    t = re.sub(r"https?://[^\s，。！？,!?\"'）)]+", _url_sub, t)

    # 2. Dates: YYYY年MM月DD日 or YYYY-MM-DD
    t = re.sub(
        r"(?<!\d)(19\d\d|20\d\d)\s*年\s*(\d{1,2})\s*月(?:\s*(\d{1,2})\s*[日号])?",
        lambda m: f"{_digits_serial_zh(m.group(1))}年{_int_to_zh(int(m.group(2)))}月"
        + (f"{_int_to_zh(int(m.group(3)))}日" if m.group(3) else ""),
        t,
    )
    t = re.sub(
        r"(?<!\d)(19\d\d|20\d\d)-(0?\d|1[0-2])-(0?\d|[12]\d|3[01])\b",
        lambda m: f"{_digits_serial_zh(m.group(1))}年{_int_to_zh(int(m.group(2)))}月{_int_to_zh(int(m.group(3)))}日",
        t,
    )
    t = re.sub(r"(?<!\d)(19\d\d|20\d\d)\s*年", lambda m: f"{_digits_serial_zh(m.group(1))}年", t)

    # 3. Time HH:MM(:SS)
    t = re.sub(
        r"(?<!\d)([01]?\d|2[0-3]):([0-5]\d)(?::([0-5]\d))?(?!\d)",
        lambda m: f"{_int_to_zh(int(m.group(1)))}点{_int_to_zh(int(m.group(2)))}分"
        + (f"{_int_to_zh(int(m.group(3)))}秒" if m.group(3) else ""),
        t,
    )

    # 4. Currency: ¥128.50 / ￥99 / $39.9
    t = re.sub(r"[¥￥]\s*(\d+(?:\.\d+)?)", lambda m: _num_str_to_zh(m.group(1)) + "元", t)
    t = re.sub(r"\$\s*(\d+(?:\.\d+)?)", lambda m: _num_str_to_zh(m.group(1)) + "美元", t)

    # 5. Percentages & Fractions
    t = re.sub(r"(-?\d+(?:\.\d+)?)\s*%", lambda m: "百分之" + _num_str_to_zh(m.group(1)), t)
    t = re.sub(
        r"(?<!\d)(\d{1,3})\s*/\s*(\d{1,4})(?!\d)",
        lambda m: f"{_int_to_zh(int(m.group(2)))}分之{_int_to_zh(int(m.group(1)))}",
        t,
    )

    # 6. Technical units (kHz, Hz, dB, ms, GB, MB)
    for rx, fn in _UNIT_MAP:
        t = rx.sub(fn, t)

    # 7. Mobile / phone numbers (11 digits starting with 1[3-9])
    t = re.sub(r"(?<!\d)(1[3-9]\d{9})(?!\d)", lambda m: _digits_serial_zh(m.group(1), telecom=True), t)

    # 8. Remaining standalone numbers
    t = re.sub(r"(?<![a-zA-Z0-9_])(-?\d+(?:\.\d+)?)(?![a-zA-Z0-9_])", lambda m: _num_str_to_zh(m.group(1)), t)
    return t


def resolve_polyphones(text: str) -> dict:
    """识别文本中的常见多音字词组并返回消歧标注报告(不破坏汉字字面,供前端诊断与音素校验使用)。"""
    t = text or ""
    hits = []
    for word, pron in _POLYPHONE_LEXICON.items():
        if word in t:
            hits.append({"word": word, "pronunciation": pron})
    return {"text": t, "polyphones": hits, "count": len(hits)}


def prepare_tts_text(text: str, channel: str = "live", expand_tn: bool = True, enabled: bool = None) -> dict:
    """v20 统一文本前端入口:
    enabled=False (或 VC_V20_FRONTEND=0) 时严格退回 vox_audio.sanitize_text,保证基线逐样本一致。"""
    if enabled is None:
        enabled = os.environ.get("VC_V20_FRONTEND", "1") == "1"
    ch = "studio" if str(channel).lower() == "studio" else "live"
    if not enabled:
        clean = sanitize_text(text, allow_style=(ch == "studio"))
        return {"text": clean, "styles": [], "channel": ch, "polyphones": [], "v20_enabled": False}

    split_txt, styles = split_style_brackets(text, mode="live")
    poly = resolve_polyphones(split_txt)["polyphones"]
    expanded_txt = expand_domain_terms(split_txt)
    body = normalize_numbers_zh(expanded_txt) if expand_tn else expanded_txt
    if ch == "studio" and styles and body:
        merged = "、".join(dict.fromkeys(s for s in styles if s))
        final_text = f"({merged}){body}"
    else:
        final_text = body
    return {
        "text": final_text,
        "body": body,
        "styles": styles,
        "channel": ch,
        "polyphones": poly,
        "v20_enabled": True,
    }
