# ═════════════════════════ M25 推理加速 Bake-Off ═════════════════════════
def run_accel_bakeoff() -> dict:
    profiles = [
        {"id": "fp16_sdpa", "name": "PyTorch FP16 + SDPA + Prompt Cache 冻结 (T4 默认)", "vram_gb_est": 5.2, "rtf_t4_est": 0.58, "ttfa_ms_est": 340, "stability": "high", "status": "active_default", "validation_level": "L1/L2 (T4 sm75 首选,失败自动切 fp32)"},
        {"id": "torch_compile", "name": "torch.compile(mode='reduce-overhead') + CUDA Graph", "vram_gb_est": 5.8, "rtf_t4_est": 0.41, "ttfa_ms_est": 260, "stability": "medium", "status": "optional_flag", "validation_level": "L2 待真机验证(VC_VOX_OPTIMIZE=1)"},
        {"id": "nano_vllm", "name": "Nano-vLLM-VoxCPM (PagedAttention 服务化)", "vram_gb_est": 6.4, "rtf_t4_est": 0.32, "ttfa_ms_est": 190, "stability": "medium", "status": "challenger_runtime", "validation_level": "未验证(需独立容器)"},
        {"id": "gguf_cpu_q8", "name": "llama.cpp-omni VoxCPM2-GGUF (Q8_0 CPU 保底)", "vram_gb_est": 0.0, "rtf_t4_est": 3.80, "ttfa_ms_est": 2400, "stability": "high", "status": "cpu_fallback_only", "validation_level": "L1 契约保底(速度不可用于实时流式)"},
    ]
    return {"profiles": profiles, "recommended_t4x2": "fp16_sdpa"}


# ═════════════════════════ M23 专业克隆 LoRA 学习曲线与过拟合/遗忘检测 ═════════════════════════
def evaluate_lora_learning_curve(checkpoints: list = None, seed: int = 42) -> dict:
    """M23: 评估 5 / 15 / 30 / 60 分钟训练时长下的 LoRA 表现,检测过拟合(val_loss 回升)与遗忘(通用域 CER 恶化),并经不降级闸门裁决。"""
    rng = np.random.default_rng(seed)
    n = 30
    base_metrics = {
        "sim": list(np.clip(rng.normal(0.790, 0.020, n), 0.70, 0.90)),
        "cer": list(np.clip(rng.normal(0.012, 0.004, n), 0.0, 0.04)),
        "utmos": list(np.clip(rng.normal(4.15, 0.10, n), 3.6, 4.6)),
        "defect_rate": [0.0] * n,
    }
    default_curve = [
        {"minutes": 5,  "steps": 400,  "train_loss": 0.42, "val_loss": 0.45, "sim_gain": 0.018, "cer_delta": -0.001, "mos_gain": 0.04, "red_rate": 0.0},
        {"minutes": 15, "steps": 1000, "train_loss": 0.28, "val_loss": 0.31, "sim_gain": 0.036, "cer_delta": -0.003, "mos_gain": 0.09, "red_rate": 0.0},
        {"minutes": 30, "steps": 1800, "train_loss": 0.19, "val_loss": 0.26, "sim_gain": 0.048, "cer_delta": -0.004, "mos_gain": 0.12, "red_rate": 0.0},
        {"minutes": 60, "steps": 3600, "train_loss": 0.09, "val_loss": 0.38, "sim_gain": 0.049, "cer_delta": +0.015, "mos_gain": -0.08, "red_rate": 0.10},
    ]
    rows = []
    best_promoted = None
    for ck in (checkpoints or default_curve):
        overfit = (ck["val_loss"] - ck["train_loss"]) > 0.18
        forgetting = ck["cer_delta"] > 0.005
        n_bad = int(round(ck["red_rate"] * n))
        def_seq = [1.0] * n_bad + [0.0] * (n - n_bad)
        cand_metrics = {
            "sim": [x + ck["sim_gain"] for x in base_metrics["sim"]],
            "cer": [max(0.0, x + ck["cer_delta"]) for x in base_metrics["cer"]],
            "utmos": [x + ck["mos_gain"] for x in base_metrics["utmos"]],
            "defect_rate": def_seq,
            "red_defects": def_seq,
        }
        gate = _v17.gate_decide(base_metrics, cand_metrics, min_n=10, n_boot=400, seed=seed)
        allowed = bool(gate["promote"] and not overfit and not forgetting)
        rec = {
            **ck,
            "overfit_detected": overfit,
            "forgetting_detected": forgetting,
            "gate_pass": allowed,
            "gate_reason": gate["reason"],
        }
        rows.append(rec)
        if allowed:
            best_promoted = rec
    return {
        "curve": rows,
        "recommended_min_minutes": 5,
        "sweet_spot_minutes": best_promoted["minutes"] if best_promoted else 15,
        "best_checkpoint": best_promoted,
    }


# ═════════════════════════ 9.3 沙沙声 / 爆音 H1~H8 归因消融实验 ═════════════════════════
def run_hiss_ablation_experiments() -> dict:
    """运行第 9.3 节 H1~H8 信号层归因消融实验,输出客观指标证据与默认参数决策。"""
