# ═════════════════════════ M31 金丝雀健康监控与自动回滚 ═════════════════════════
def canary_health_monitor(lineage: _v17.Lineage, recent_turns: list, max_red_rate: float = 0.05, max_cer: float = 0.12) -> dict:
    """M31: 监控金丝雀或当前活跃版本最近轮次的质量指标;一旦人为注入劣化或指标越界,立即触发自动回滚。"""
    cur = lineage.champion()
    if not recent_turns:
        return {"action": "none", "rolled_back": False, "active": cur}

    n = len(recent_turns)
    red_cnt = sum(1 for t in recent_turns if t.get("defect_level") == "red" or not t.get("pass", True))
    avg_cer = float(np.mean([float(t.get("cer", 0.0)) for t in recent_turns]))
    red_rate = red_cnt / float(n)

    for t in recent_turns:
        ok = (t.get("defect_level") != "red") and bool(t.get("pass", True)) and float(t.get("cer", 0.0)) <= max_cer
        rb_step = lineage.canary(ok, min_uses=max(2, len(recent_turns)), max_bad_rate=max_red_rate)
        if rb_step.get("rolled_back"):
            return {"action": "auto_rollback", "rolled_back": True, "red_rate": red_rate, "avg_cer": avg_cer, "active": lineage.champion(), "detail": rb_step}

    if (red_rate > max_red_rate or avg_cer > max_cer) and lineage.champion() != "m_000":
        reason = f"金丝雀自动回滚触发: red_rate={red_rate:.2%}, avg_cer={avg_cer:.2%}"
        rb = lineage.rollback(reason=reason)
        return {"action": "auto_rollback", "rolled_back": bool(rb.get("ok")), "red_rate": red_rate, "avg_cer": avg_cer, "active": lineage.champion(), "detail": rb}

    return {"action": "healthy", "rolled_back": False, "red_rate": red_rate, "avg_cer": avg_cer, "active": lineage.champion()}
