def acoustic_matrix_summary():
    return {
        "version": "v21.0",
        "total_vectors": len(ACOUSTIC_CALIBRATION_MATRIX_V21),
        "sr_supported": [24000, 48000],
        "first_grid_id": ACOUSTIC_CALIBRATION_MATRIX_V21[0]["grid_id"],
    }

def query_acoustic_profile(sample_rate=48000, freq_hz=1000.0):
    sr = int(sample_rate)
    f = float(freq_hz)
    best = min((x for x in ACOUSTIC_CALIBRATION_MATRIX_V21 if x['sample_rate'] == sr), key=lambda x: abs(x['center_freq_hz'] - f))
    return best
