def v15_forensics_turn(turn):
    """合成结束后(线程池里)对「实际发给浏览器的 PCM」取证;只分析前 120 秒,不阻塞事件循环。"""
    if _v15 is None or not _v15.on("FORENSICS") or not turn.gen_pcm:
        return

    def work():
        try:
            pcm = np.frombuffer(b"".join(turn.gen_pcm)[: 2 * SR * 120], dtype="<i2")
            rep = _v15.analyze(pcm)
            V15C.add_turn(rep)
        except Exception as e:  # noqa: BLE001
            log.warning("v15 取证失败(忽略): %s", e)
    try:
        LOOP.run_in_executor(None, work)
    except Exception:  # noqa: BLE001
        pass


