@app.api_route("/api/artifacts/{aid}/turn.wav", methods=["GET", "HEAD"])
async def api_art_turn(aid: str, request: Request, format: str = "wav"):
    try:
        p, fe, m = ART.resolve(aid, cur_lib(), "turn")
        if format == "flac":
            fp = await asyncio.get_running_loop().run_in_executor(None, lambda: ART.to_flac(p, fe))
            return serve_file(request, fp, fe["pcm_sha256"], "ai-synthetic_%s_full.flac" % aid, "audio/flac", "flac-")
        if format != "wav":
            raise art.ArtifactError("bad_format", "format 只支持 wav / flac", 400)
        return serve_file(request, p, fe["sha256"], "ai-synthetic_%s_full.wav" % aid)
    except art.ArtifactError as e:
        return art_err(e)


