def v16_state():
    if _v16 is None:
        return {"available": False}
    return {"available": True, "version": _v16.VERSION, "switches": _v16.switches(), "counters": V16C.snapshot(), "ttfa_stages": V16T.summary(), "ttfa_biggest": V16T.biggest(),
            "params": {"hf_ref_warn_db": _v16.HF_REF_WARN_DB, "hf_out_warn_db": _v16.HF_OUT_WARN_DB, "dc_fix_threshold": _v16.DC_FIX_THRESHOLD}}


def v16_forensics_turn(turn):
    """v16 取证(线程池里):v15.analyze 全部指标 + 安静处 HF 底噪(沙沙声启发式)+ 直流。只测量,不改任何音频。"""
    if _v16 is None or not _v16.on("AUDIO") or not turn.gen_pcm:
        return

    def work():
        try:
            pcm = np.frombuffer(b"".join(turn.gen_pcm)[: 2 * SR * 120], dtype="<i2")
            V16C.add_turn(_v16.audio_guard_report(pcm))
        except Exception as e:  # noqa: BLE001
            log.warning("v16 取证失败(忽略): %s", e)
    try:
        LOOP.run_in_executor(None, work)
    except Exception:  # noqa: BLE001
        pass


def v16_turn_timing(turn, first_ms, model_first_ms, queue_ms):
    """M7:把已有的三个测量值记成分段:gateway=队列(轮开始→首段派发) · first_frames=模型首块(prefill+前N帧+首块解码,GPU 进程内未再细分) · ws_play=其余(规划保持/桥接/后处理/WebSocket)。"""
    if _v16 is None or V16T is None or not _v16.on("TTFA") or first_ms is None:
        return
    try:
        V16T.add("gateway", queue_ms)
        V16T.add("first_frames", model_first_ms)
        V16T.add("ws_play", max(0.0, float(first_ms) - float(queue_ms or 0) - float(model_first_ms or 0)))
    except Exception:  # noqa: BLE001
        pass


