    GEN_AUDIO.clear()
    n_art = 0
    if ART is not None:                                             # 范围明确:只删当前语音库的生成产物(?artifacts=all 才删全部语音库)
        n_art = ART.purge(lib_id, everything=(request.query_params.get("artifacts") == "all"))
    n = 0
    import shutil
