def build_report():
    hw_both = bool(POOL) and len(POOL.workers) >= 2 and all(w.synth_segs > 0 for w in POOL.workers)
    tr = read_train_progress()
    ms = list(METRICS)
    items = []

    def add(i, title, status, detail):
        items.append({"id": i, "title": title, "status": status, "detail": detail})
    if MOCK:
        add(1, "真实硬件(T4 双卡)", "未验证", "当前是 MOCK 引擎,不能证明任何真实硬件/质量结论")
    else:
        names = [r["name"] for r in GPU_ROWS.values()]
        add(1, "真实硬件(T4 双卡)", "通过" if (hw_both and len(names) >= 2) else "未运行", "推理 worker 实际合成句数: %s;GPU: %s" % ([w.synth_segs for w in POOL.workers] if POOL else [], names) +
            ";训练双卡: " + ("见训练状态 ddp_check=%s" % json.dumps(tr.get("ddp_check"), ensure_ascii=False) if tr.get("ddp_check") else "未运行"))
    short = [m for m in ms if (m.get("chars") or 0) < 40]
    long_ = [m for m in ms if (m.get("chars") or 0) >= 200]
    bad = [m for m in ms if m.get("underruns") or m.get("rebuffers") or m.get("gaps") or m.get("dups") or m.get("foreign") or m.get("integrity_fail")]
    if not ms:
        add(2, "播放连续性(underrun=0, rebuffer=0)", "未运行", "还没有浏览器上报的播放测量。请在网页里合成短文本、长文本、连续多轮")
    elif bad:
        add(2, "播放连续性(underrun=0, rebuffer=0)", "失败", "%d/%d 轮出现欠载/重缓冲/漏块/重复块/串轮" % (len(bad), len(ms)))
    else:
        miss = [n for n, v in (("短文本", short), ("长文本(≥200字)", long_), ("连续多轮(≥3轮)", ms if len(ms) >= 3 else [])) if not v]
        add(2, "播放连续性(underrun=0, rebuffer=0)", "通过" if not miss and not MOCK else "未运行", "已测 %d 轮,全部无欠载" % len(ms) + (";尚缺: " + "、".join(miss) if miss else "") + (";MOCK 不算数" if MOCK else ""))
    stress = []
    if EVENTS["reconnect_resumed"]:
        stress.append("WebSocket 重连续传 %d 次" % EVENTS["reconnect_resumed"])
    if EVENTS["visibility"]:
        stress.append("页面切换 %d 次" % EVENTS["visibility"])
    add(3, "压力与网络测试(慢生成/抖动/切页/重连/GPU 忙)", "已部分观测" if stress else "未运行", ";".join(stress) or "尚未观测到。极端断网情况不承诺连续播放")
    cold = [m["ttfa_ms"] for m in ms if m.get("cold") and m.get("ttfa_ms")]
    warm = [m["ttfa_ms"] for m in ms if not m.get("cold") and m.get("ttfa_ms")]
    add(4, "性能报告(TTFA/RTF/chunk 间隔/水位)", "已测量" if (cold or warm) else "未运行", "冷 TTFA %s;热 TTFA %s" % (pcts(cold), pcts(warm)))
    srv_err = [t for t in TURN_LOG if t.get("errors")]
    add(5, "音频完整性(样本数/序号/END/边界/静音/削波)", ("失败" if srv_err else ("通过" if TURN_LOG and not MOCK else "未运行")), "服务端 %d 轮,其中 %d 轮有损坏句子" % (len(TURN_LOG), len(srv_err)))
    sims = [v for t in TURN_LOG for v in []]
    add(6, "克隆质量(口语/歌声,保留文本评估)", "未验证", "原始声纹 cosine 已按轮显示;%s;A/B 试听投票 %d 次;歌声克隆:不支持/未验证" % ("已有校准文件" if CAL else "未校准:不可给出人耳相似度百分比", len(EVENTS["ab_votes"])))
    wm = weights_match()
    add(7, "双卡一致性(同一权重/同一配置)", "通过" if wm else ("失败" if wm is False else "未运行"), "权重指纹一致=%s;sha256=%s;不承诺逐采样点相同,跨卡听感需人工 A/B" % (wm, SEC["model_sha256"]))
    add(8, "环境", "已记录", json.dumps(backend_summary(), ensure_ascii=False, default=str)[:600])
    v13_report_items(add)
    v14_report_items(add)
    v15_report_items(add)
    v16_report_items(add)
    v17_report_items(add)
    return {"generated": time.strftime("%F %T"), "mock": MOCK, "items": items, "turns_gateway": list(TURN_LOG)[-40:], "turns_browser": ms[-40:], "events": EVENTS, "v13": v13_state(), "v15": v15_state(), "v16": v16_state(), "v17": v17_state(),
            "per_gpu": {str(i): {"F_ms": round(W(i)["F"] * 1000, 1), "D_ms": round(W(i)["D"] * 1000, 1), "PRE_ms": round(W(i)["PRE"] * 1000), "chunk_gap_ms": pcts([g * 1000 for g in W(i)["gaps"]])}
                        for i in (range(len(POOL.workers)) if POOL else [])}}


@app.get("/api/report")
async def api_report():
    return build_report()


@app.post("/api/report/save")
async def api_report_save():
    REPORT_DIR.mkdir(parents=True, exist_ok=True)
    p = REPORT_DIR / ("report_%s.json" % time.strftime("%Y%m%d_%H%M%S"))
    p.write_text(json.dumps(build_report(), ensure_ascii=False, indent=2, default=str), encoding="utf-8")
    return {"ok": True, "path": str(p)}


def replay(sess, uid, next_seq):
    t = sess.turns.get(uid)
    if t is None:
        EVENTS["resume_fail"] += 1
        sess.send({"type": "resume_fail", "turn": uid})
        return
    frames = t.log[next_seq:]
    sess.send({"type": "resume_ok", "turn": uid, "from": next_seq, "frames": len(frames)})
    for f in frames:
        sess.send_bin(f)
    t.replayed += len(frames)
    EVENTS["reconnect_resumed"] += 1
    if t.done_msg:
        sess.send(t.done_msg)
    pump(t)


def on_ack(sess, m):
    t = sess.turns.get(int(m.get("turn") or 0))
    if t is None:
        return
    t.has_acks = True
    t.played = max(t.played, int(m.get("played") or 0))
    t.level_ms = m.get("level_ms")
    pump(t)
    if POOL:
        POOL.schedule()


@app.websocket("/ws")
async def ws_endpoint(ws: WebSocket):
    await ws.accept()
    sess = None

    def adopt(sid):
        nonlocal sess
        sid = (sid or "")[:48] or uuid.uuid4().hex[:12]
        old = SESS_BY_SID.get(sid)
        resumed = False
        if old is not None:
            if old.attached:
                old.detach()
            sess, resumed = old, True
        else:
            sess = Session(sid)
            SESS_BY_SID[sid] = sess
        SESSIONS.add(sess)
        sess.attach(ws)
        return resumed

    try:
        while True:
            raw = await ws.receive_text()
            try:
                m = json.loads(raw)
            except ValueError:
                continue
            k = m.get("type")
            if sess is None:
                resumed = adopt(m.get("sid") if k == "hello" else None)
                sess.send({"type": "hello_ok", "sid": sess.sid, "resumed": resumed, "server_t": time.time()})
                sess.send(state_public())
                if k == "hello":
                    rs = m.get("resume")
                    if resumed and rs and sess.turns.get(int(rs.get("turn") or 0)) is not None:
                        replay(sess, int(rs["turn"]), int(rs.get("next_seq") or 0))
                    elif resumed and sess.turn is not None and not sess.turn.closed:
                        cancel_turn(sess)                  # 页面重新加载:旧轮次没人接收了
                    continue
            if k == "ping":
                sess.send({"type": "pong", "t": m.get("t")})
            elif k == "ack":
                on_ack(sess, m)
            elif k == "resume":
                replay(sess, int(m.get("turn") or 0), int(m.get("next_seq") or 0))
            elif k == "metrics":
                m.pop("type", None)
                METRICS.append(m)
            elif k == "event":
                n = m.get("name")
                if n == "visibility":
                    EVENTS["visibility"] += 1
                elif n == "ab_vote":
                    EVENTS["ab_votes"].append({"choice": m.get("choice"), "t": time.time()})
            elif k == "chat":
                txt = str(m.get("text") or "").strip()
                if txt:
                    start_turn(sess, txt[:20000], m.get("opts") or {}, m.get("ref"))
            elif k == "say":
                txt = str(m.get("text") or "").strip()
                if txt:
                    o = dict(m.get("opts") or {})
                    o["tts"] = True
                    start_turn(sess, txt[:20000], o, m.get("ref"), say_only=True)
            elif k == "stop":
                cancel_turn(sess)
                sess.send({"type": "stopped"})
            elif k == "reset":
                cancel_turn(sess)
                sess.history = []
                sess.send({"type": "reset_ok"})
    except WebSocketDisconnect:
        pass
    except Exception as e:  # noqa: BLE001
        log.info("ws 结束: %s", e)
    finally:
        if sess is not None:
            if sess.ws is ws:
                sess.detach()          # 保留会话 RESUME_GRACE_S 秒:断线重连后按 next_seq 精确续传;超时由 gpu_loop 回收并取消轮次


@app.websocket("/monitor")
async def monitor_ws(ws: WebSocket):
    await ws.accept()
    MONITORS.add(ws)

    async def rd():
        try:
            while True:
                await ws.receive_text()
        except Exception:  # noqa: BLE001
            pass

    rt = asyncio.get_running_loop().create_task(rd())
    try:
        while not rt.done():
            await ws.send_text(json.dumps({"event": "gpu_status", "gpus": gpu_table(), **{"gpu%d" % w.idx: w.mem[2] for w in (POOL.workers if POOL else [])}}, ensure_ascii=False))
            await ws.send_text(json.dumps(read_train_progress(), ensure_ascii=False))
            await asyncio.sleep(2.0)
    except Exception:  # noqa: BLE001
        pass
    finally:
        rt.cancel()
        MONITORS.discard(ws)


@app.websocket("/stream")
async def stream_ws(ws: WebSocket):
    """兼容简化协议: 发 {"text": "..."} -> 收原始 PCM(int16, 24kHz, 无头) -> 收 {"event":"done","similarity":0.97}"""
    await ws.accept()
    sess = Session("legacy-%s" % uuid.uuid4().hex[:8])
    sess.legacy = True
    sess.attach(ws)
    SESSIONS.add(sess)
    st = {"deadline": None, "done": True, "sim": None}
    out_q = sess.q

    async def finish():
        st["done"] = True
        st["deadline"] = None
        await ws.send_text(json.dumps({"event": "done", "similarity": st["sim"]}))

    async def sender():
        try:
            while True:
                try:
                    m = await asyncio.wait_for(out_q.get(), 0.5)
                except asyncio.TimeoutError:
                    if st["deadline"] and not st["done"] and time.time() > st["deadline"]:
                        await finish()
                    continue
                if isinstance(m, (bytes, bytearray)):
                    sess.q_bytes -= len(m)
                    if len(m) > HEADER_SIZE:
                        await ws.send_bytes(bytes(m[HEADER_SIZE:]))
                    continue
                o = json.loads(m)
                t = o.get("type")
                if t == "sim":
                    st["sim"] = o.get("value") if o.get("value") is not None else st["sim"]
                    if o.get("final") and not st["done"]:
                        await finish()
                elif t == "turn_done":
                    st["deadline"] = time.time() + 3.0
                elif t == "error":
                    st["done"] = True
                    await ws.send_text(json.dumps({"event": "error", "message": o.get("msg", "")}, ensure_ascii=False))
                elif t == "warn":
                    await ws.send_text(json.dumps({"event": "warn", "message": o.get("msg", "")}, ensure_ascii=False))
        except Exception:  # noqa: BLE001
            pass

    # legacy 通道自己消费队列(不走 Session._sender),所以取消默认 sender
    if sess.sender:
        sess.sender.cancel()
    stt = asyncio.get_running_loop().create_task(sender())
    try:
        while True:
            raw = await ws.receive_text()
            try:
                m = json.loads(raw)
            except ValueError:
                m = {"text": raw}
            if m.get("type") == "ping" or m.get("event") == "ping":
                await ws.send_text(json.dumps({"event": "pong"}))
                continue
            if m.get("type") == "stop":
                cancel_turn(sess)
                continue
            txt = str(m.get("text") or "").strip()
            if not txt:
                continue
            if VOICE["state"] != "ready":
                await ws.send_text(json.dumps({"event": "error", "message": "声音还没有克隆好,请先在网页里录入参考语音"}, ensure_ascii=False))
                continue
            st.update(done=False, sim=None, deadline=None)
            start_turn(sess, txt[:20000], {"tts": True}, None, say_only=True)
    except WebSocketDisconnect:
        pass
    except Exception as e:  # noqa: BLE001
        log.info("stream 结束: %s", e)
    finally:
        cancel_turn(sess)
        SESSIONS.discard(sess)
        stt.cancel()


def _hash_model():
    try:
        p = Path(MODEL)
        if not p.is_dir():
            from huggingface_hub import snapshot_download
            p = Path(snapshot_download(MODEL, local_files_only=True))
        f = p / "model.safetensors"
        if not f.exists():
            return
        h = hashlib.sha256()
        with open(f, "rb") as fh:
            for blk in iter(lambda: fh.read(1 << 23), b""):
                h.update(blk)
        SEC["model_sha256"], SEC["model_file"] = h.hexdigest(), str(f)
        log.info("模型文件 sha256 %s (%s)", SEC["model_sha256"][:16], f)
    except Exception as e:  # noqa: BLE001
        log.warning("模型哈希失败: %s", e)


