def _int_to_zh(n: int) -> str:
    if n == 0:
        return "零"
    if n < 0:
        return "负" + _int_to_zh(-n)
    parts: list[str] = []
    wan_idx = 0
    wan_units = ["", "万", "亿"]
    while n > 0 and wan_idx < len(wan_units):
        seg = n % 10000
        if seg > 0:
            s_str = ""
            zero_flag = False
            for i in range(4):
                d = seg % 10
