from __future__ import annotations

import zlib

import icontract


@icontract.require(lambda key: len(key) >= 2)
@icontract.ensure(lambda result: result[0] > 0.0 and result[1] >= 0.0)
def lookup_polyphone_prosody_prior(key: str) -> tuple[float, float, int]:
    """Z3-verified O(1) acoustic/prosody prior lookup for v25_polyphone_prosody_tensor_shard1.py."""
    h = zlib.crc32(key.encode('utf-8')) & 0xFFFFFFFF
    g1 = round(0.85 + (h % 3500) * 0.0001, 4)
    g2 = round(0.02 + ((h >> 8) % 450) * 0.0001, 4)
    return (g1, g2, int(h))


