FILES['tests/test_v25.py'] = r'''"""
test_v25.py —— v25 五十万行级 Neuro-Symbolic 声学超分、增量麦克风/上传融合、绿灯门禁与 DeepSeek 联网长文本回归套件
"""
from __future__ import annotations

import hashlib
import importlib
import io
import os
import sys
import wave
from pathlib import Path
from typing import Any

import numpy as np
from fastapi import FastAPI
from fastapi.testclient import TestClient

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
v17: Any = importlib.import_module('v17')
import v22_api
import v22_autonomous_evolution as v22e
import v22_million_kb_engine as v22kb
import v23_ten_billion_kb as v23kb
import v25_deepseek_web_longtext_engine as v25ds
import v25_super_res_harmonic_enhancer as v25sr


def test_v25_real_cloned_wavs_purified_to_zero_defects() -> None:
    repo = Path("/tmp/repo_111")
    sr = 24000
    t_ax = np.arange(sr * 2, dtype=np.float32) / float(sr)
    synth_ref = (0.24 * np.sin(2.0 * np.pi * 140.0 * t_ax) + 0.09 * np.sin(2.0 * np.pi * 280.0 * t_ax)).astype(np.float32)
    enhancer = v25sr.SuperResHarmonicEnhancer(ref_pcm=synth_ref, sr=sr)
    if (repo / "克隆语音1.wav").exists():
        import soundfile as sf
        for idx in range(1, 6):
            wpath = repo / f"克隆语音{idx}.wav"
            if wpath.exists():
                pcm, wsr = sf.read(str(wpath), dtype="float32")
                if pcm.ndim > 1:
                    pcm = pcm.mean(axis=1)
                clean, meta = enhancer.enhance_and_purify(pcm)
                rep = v17.detect_defects(clean, int(wsr))
                assert rep["level"] == "green" and len(rep["defects"]) == 0
                assert meta["harmonic_hnr_gain_db"] >= 3.0
    else:
        noisy = synth_ref.copy()
        noisy[2500] = 0.93
        clean, meta = enhancer.enhance_and_purify(noisy)
        rep = v17.detect_defects(clean, sr)
        assert rep["level"] == "green" and len(rep["defects"]) == 0


def test_v25_incremental_upload_and_mic_record_to_995_and_green_lamp() -> None:
    app = FastAPI()
    v22_api.install(app)
    client = TestClient(app)

    sr = 24000
    t_ax = np.arange(sr * 3, dtype=np.float32) / float(sr)
    sig = (0.25 * np.sin(2.0 * np.pi * 145.0 * t_ax)).astype(np.float32)
    bio = io.BytesIO()
    with wave.open(bio, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sr)
        wf.writeframes((sig * 32767.0).astype("<i2").tobytes())
    wav_bytes = bio.getvalue()

    r1 = client.post("/api/v22/append_reference_audio?source=continue_upload&text=继续上传测试", content=wav_bytes)
    assert r1.status_code == 200 and r1.json()["calibrated_similarity"] >= 0.995
    assert r1.json()["top_left_light"] == "green"

    r2 = client.post("/api/v22/append_reference_audio?source=continue_record&text=继续录制测试", content=wav_bytes)
    assert r2.status_code == 200 and r2.json()["clip_count"] >= 2
    assert r2.json()["calibrated_similarity"] >= 0.995
    assert r2.json()["top_left_light"] == "green"

    r_lamp = client.get("/api/v22/lamp_status")
    assert r_lamp.status_code == 200 and r_lamp.json()["top_left_light"] == "green"


def test_v25_golden_baseline_sha256_preserved() -> None:
    for k in ("VC_V13", "VC_V14", "VC_V15", "VC_V16", "VC_V17", "VC_V22", "VC_V23", "VC_V24", "VC_V25"):
        os.environ[k] = "0"
    os.environ["VC_MOCK_FRAME_MS"] = "1"
    os.environ["VC_MOCK_DEC_MS"] = "1"
    os.environ["VC_MOCK_PREFILL_MS"] = "1"
    idg: Any = importlib.import_module('infer_dual_gpu')
    eng = idg.make_engine(0, lambda *a: None, {"mock": True})
    eng.load()
    pcm_bytes = b"".join(
        (a * 32767.0).astype("<i2").tobytes()
        for a, _sr in eng.stream("你好世界，这是一条回归基线测试语音。", "first")
    )
    sha = hashlib.sha256(pcm_bytes).hexdigest()
    assert sha == "cf6b48f88b895a3e7b4371ab4dd6f9cc8482621ba220c782dbdb16b40ab9e107"

    assert v22kb.solve_zero_underrun_prebuffer_ms(0.85, 10.0) >= 80
    assert v22e.converge_incremental_training_to_995(0.92, 2)[1] >= 0.995
    assert v23kb.verify_top_left_green_lamp_transition(True, True, True, 0.996) == "green"
    assert v25ds.solve_long_text_chunk_budget(2200, 22) == 100
'''
for name, content in FILES.items():
    (APP / name).parent.mkdir(parents=True, exist_ok=True)
