# ───────────────────────── 2. 依赖 ─────────────────────────
banner("2/6  安装依赖(独立环境,不破坏 Kaggle 自带的 PyTorch;首次约 3~6 分钟)")
PY = sys.executable
VOX_READY, VOX_MSG = False, "未检查"
if not TEST:
    ok_marker = VENV / ".ok_v19"
